comms.text:
@1 וְצַלֵיתִי קֳדָם יְיָ בְּעִדָנָא הַהִיא לְמֵימָר:
@2 יְיָ אֱלֹהִים אַתְּ שָׁרֵיתָא לְאַחֲזָאָה יָת עַבְדָךְ יָת רְבוּתָךְ וְיָת יְדָךְ תַּקֶפְתָּא דִי אַתְּ הוּא אֱלָהָא דִשְׁכִנְתָּךְ בִּשְׁמַיָא מִלְעֵלָא וְשַׁלִיט בְּאַרְעָא וְלֵית דְיַעְבֵּד כְּעוֹבְדָיךְ וּכְגִבָּרְתָּךְ:
@3 אֵעִבַר כְּעַן וְאֶחֱזֵי יָת אַרְעָא טַבְתָא דִּי בְּעִבְרָא דְיַרְדְנָא טוּרָא טָּבָא הָדֵין וּבֵית מַקְדָשָׁא:
@4 וַהֲוָה רְגַז מִן קֳדָם יְיָ עֲלַי בְּדִילְכוֹן וְלָא קַבִּיל מִנִי וַאֲמַר יְיָ לִי סַגִי לָךְ לָא תוֹסֵף לְמַלָלָא קֳדָמַי עוֹד בְּפִתְגָמָא הָדֵין:
@5 סַק לְרֵישׁ רָמָתָא וּזְקוֹף עֵינָיךְ לְמַעֲרָבָא וּלְצִפּוּנָא וְלִדְרוֹמָא וּלְמָדִינְחָא וַחֲזֵי בְעֵינָיךְ אֲרֵי לָא תְעִבַר יָת יַרְדְנָא הָדֵין:
@6 וּפַקֵד יָת יְהוֹשֻׁעַ וְתַקֶפְהִי וְאַלֶמְהִי אֲרֵי הוּא יֵעִבַר קֳדָם עַמָא הָדֵין וְהוּא יַחְסֵן יָתְהוֹן יָת אַרְעָא דִי תֶחֱזֵי:
@7 וִיתֵבְנָא בְחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר:
@8 וּכְעַן יִשְׂרָאֵל שְׁמַע לִקְיָמַיָא וּלְדִינַיָא דִי אֲנָא מְאַלֵף יָתְכוֹן לְמֶעְבַּד בְּדִיל דְתֵיחוּן וְתֵיתוּן וְתֵירְתוּן יָת אַרְעָא דִי יְיָ אֱלָהָא דַאֲבָהָתְכוֹן יָהֵב לְכוֹן:
@9 לָא תוֹסְפוּן עַל פִּתְגָמָא דִי אֲנָא מְפַקֵד יָתְכוֹן וְלָא תִמְנְעוּן מִנֵהּ לְמִטַר יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן דִי אֲנָא מְפַקֵד יָתְכוֹן:
@10 עֵינֵיכוֹן חָזָן יָת דִי עֲבַד יְיָ בְּבַעַל פְּעוֹר אֲרֵי כָּל גַבְרָא דִי אֲזַל בָּתַר בַּעַל פְּעוֹר שֵׁצְיֵהּ יְיָ אֱלָהָךְ מִבֵּינָךְ:
@11 וְאַתּוּן דְאַדְבֶּקְתּוּן בְּדַחַלְתָּא דַיְיָ אֱלָהֲכוֹן קַיָמִין כֻּלְכוֹן יוֹמָא דֵין:
@12 חֲזוֹ דְאַלֵפִית יָתְכוֹן קְיָמַיָא וְדִינַיָא כְּמָא דִי פַקְדַנִי יְיָ אֱלָהָי לְמֶעְבַּד כֵּן בְּגוֹ אַרְעָא דִי אַתּוּן עַלִין תַּמָן לְמֵירְתַהּ:
@13 וְתִטְרוּן וְתַעְבְּדוּן אֲרֵי הִיא חָכְמַתְכוֹן וְסוּכְלְתָנוּתְכוֹן לְעֵינֵי עַמְמַיָא דִי יִשְׁמְעוּן יָת כָּל קְיָמַיָא הָאִלֵין וְיֵימְרוּן לְחוֹד עַם חַכִּים וְסוּכְלְתָן עַמָא רַבָּא הָדֵין:
@14 אֲרֵי מָן עַם רַב דִי לֵהּ אֱלָהָא קָרִיב לֵהּ לְקַבָּלָא צְלוֹתֵהּ בְּעִדַן עַקְתֵהּ כַּייָ אֱלָהָנָא בְּכָל עִדָן דַאֲנַחְנָא מְצַלִין קֳדָמוֹהִי:
@15 וּמָן עַם רַב דִי לֵהּ קְיָמִין וְדִינִין קַשִׁיטִין כְּכֹל אוֹרַיְתָא הָדָא דִי אֲנָא יָהֵב קֳדָמֵכוֹן יוֹמָא דֵין:
@16 לְחוֹד אִסְתַּמַר לָךְ וְטַר נַפְשָׁךְ לַחֲדָא דִילְמָא תִנְשֵׁי יָת פִּתְגָמַיָא דִי חֲזוֹ עֵינָיִךְ וְדִילְמָא יְעִדוּן מִלִבָּךְ כֹּל יוֹמֵי חַיָיךְ וּתְהוֹדְעִנוּן לִבְנָיךְ וְלִבְנֵי בְנָיִךְ:
@17 יוֹמָא דִי קַמְתָּא קֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב כַּד אֲמַר יְיָ לִי כְּנוֹשׁ קֳדָמַי יָת עַמָא וְאַשְׁמְעִנוּן יָת פִּתְגָמָי דִי יֵלְפוּן לְמִדְחַל קֳדָמַי כָּל יוֹמַיָא דִי אִנוּן קַיָמִין עַל אַרְעָא וְיָת בְּנֵיהוֹן יְאַלְפוּן:
@18 וּקְרֶבְתּוּן וְקַמְתּוּן בְּשִׁפּוֹלֵי טוּרָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא עַד צֵית שְׁמַיָא חֲשׁוֹכָא עֲנָנָא וַאֲמִיטְתָא:
@19 וּמַלִיל יְיָ עִמְכוֹן מִגוֹ אֶשְׁתָא קַל פִּתְגָמִין אַתּוּן שָׁמְעִין וּדְמוּת לֵיתֵיכוֹן חָזָן אֱלָהֵן קָלָא:
@20 וְחַוִי לְכוֹן יָת קְיָמֵהּ דִי פַקִיד יָתְכוֹן לְמֶעְבַּד עַשְׂרָא פִּתְגָמִין וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא:
@21 וְיָתִי פַּקִיד יְיָ בְּעִדְנָא הַהִיא לְאַלָפָא יַתְכוֹן קְיָמִין וְדִינִין לְמֶעְבָּדְכוֹן יָתְהוֹן בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@22 וְתִסְתַּמְרוּן לַחֲדָא לְנַפְשָׁתֵיכוֹן אֲרֵי לָא חֲזֵיתוּן כָּל דְמוּת בְּיוֹמָא דִי מַלִיל יְיָ עִמְכוֹן בְּחֹרֵב מִגוֹ אֶשָׁתָא:
@23 דִילְמָא תְּחַבְּלוּן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כָּל צוּרָא דְמוּת דְכַר אוֹ נֻקְבָא:
@24 דְמוּת כָּל בְּעִירָא דִי בְאַרְעָא דְמוּת כָּל צִפַּר גַדְפָא דִי פָּרַח בַּאֲוֵר רְקִיע שְׁמַיָא:
@25 דְמוּת כָּל רִחֲשָׁא דִי בְאַרְעָא דְמוּת כָּל נוּנֵי דִי בְמַיָא מִלְרַע לְאַרְעָא:
@26 וְדִילְמָא תִזְקוֹף עֵינָיךְ לִשְׁמַיָא וְתֶחֱזֵי יָת שִׁמְשָׁא וְיָת סִיהֲרָא וְיָת כּוֹכְבַיָא כֹּל חֵילֵי שְׁמַיָא וְתִטְעֵי וְתִסְגוּד לְהוֹן וְתִפְלְחִנוּן דִי זַמִין יְיָ אֱלָהָךְ יָתְהוֹן לְכֹל עַמְמַיָא תְּחוֹת כָּל שְׁמַיָא:
@27 וְיָתְכוֹן קָרִיב יְיָ לְדַחַלְתֵּהּ וְאַפֵּק יָתְכוֹן מִכּוּרָא דְפַרְזְלָא מִמִצְרָיִם לְמֶהֱוֵי לֵהּ לְעַמָא אַחֲסָנָא כְּיוֹמָא הָדֵין:
@28 וּמִן קֳדָם יְיָ הֲוָה רְגַז עֲלַי עַל פִּתְגָמֵיכוֹן וְקַיִים בְּדִיל דְלָא לְמֵעֲבַר יָת יַרְדְנָא וּבְדִיל דְלָא לְמֵיעַל לְאַרְעָא טָבָא דִי יְיָ אֱלָהָךְ יָהֵבּ לָךְ אַחֲסָנָא:
@29 אֲרֵי אֲנָא מָאִית בְּאַרְעָא הָדָא לֵית אֲנָא עָבֵר יָת יַרְדְנָא וְאַתּוּן עָבְרִין וְתֵירְתוּן יָת אַרְעָא טָבָא הָדָא:
@30 אִסְתַּמָרוּ לְכוֹן דִילְמָא תִתְנְשׁוּן יָת קְיָמָא דַיְיָ אֱלָהֲכוֹן דִי גְזַר עִמְכוֹן וְתַעְבְּדוּן לְכוֹן צֶלֶם דְמוּת כֹּלָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@31 אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ אֶשָׁא אָכְלָא הוּא אֵל קַנָא:
@32 אֲרֵי תוֹלְדוּן בְּנִין וּבְנֵי בְנִין וְתִתְעַתְּקוּן בְּאַרְעָא וּתְחַבְּלוּן וְתַעְבְּדוּן צֶלֶם דְמוּת כֹּלָא וְתַעְבְּדוּן דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְאַרְגָזָא קֳדָמוֹהִי:
@33 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא אֲרֵי מֵיבַד תֵּיבְדוּן בִּפְרִיעַ מֵעַל אַרְעָא דִי אַתּוּן עָבְרִין יָת יַרְדְנָא לְתַמָן לְמֵירְתַהּ לָא תוֹרְכוּן יוֹמִין עֲלַהּ אֲרֵי אִשְׁתְּצָאָה תִּשְׁתֵּצוּן:
@34 וִיבַדַר יְיָ יָתְכוֹן בְּעַמְמַיָא וְתִשְׁתָּאֲרוּן עַם דְמִנְיָן בְּעַמְמַיָא דִי יְדַבַּר יְיָ יָתְכוֹן לְתַמָן:
@35 וְתִפְלְחוּן תַּמָן לְעַמְמַיָא פָלְּחֵי טַעֲוָתָא עֹבַד יְדֵי אֱנָשָׁא אָעָא וְאַבְנָא דִי לָא יֶחֱזוּן וְלָא שָׁמְעִין וְלָא אָכְלִין וְלָא מְרִיחִין:
@36 וְתִתְבְּעוּן מִתַּמָן יָת דַחֲלְתָּא דַייָ אֱלָהָךְ וְתִשְׁכָּח אֲרֵי תִבְעֵי מִן קֳדָמוֹהִי בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@37 כַּד יֵיעוֹק לָךְ וְיַשְׁכְּחֻנָךְ כֹּל פִּתְגָמַיָא הָאִלֵין בְּסוֹף יוֹמַיָא וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ:
@38 אֲרֵי אֱלָהָא רַחֲמָנָא יְיָ אֱלָהָךְ לָא יִשְׁבְּקִנָךְ וְלָא יְחַבְּלִנָךְ וְלָא יִתִּנְשֵׁי יָת קְיָמָא דַאֲבָהָתָךְ דִי קַיִים לְהוֹן:
@39 אֲרֵי שְׁאֵל כְּעַן לְיוֹמַיָא קַדְמָאֵי דַהֲווֹ קֳדָמָךְ לְמִן יוֹמָא דִי בְרָא יְיָ אָדָם עַל אַרְעָא וּלְמִסְיָפֵי שְׁמַיָא וְעַד סְיָפֵי שְׁמַיָא הַהֲוָה כְּפִתְגָמָא רַבָּא הָדֵין אוֹ הַאִשְׁתְּמַע כְּוָתֵהּ:
@40 הַשְׁמַע עַמָא קַל מֵימְרָא דַיְיָ מְמַלֵל מִגוֹ אֶשָׁתָא כְּמָא דִי שְׁמַעַתְּ אַתְּ וְיִתְקַיָם:
@41 אוֹ נִסִין דִי עֲבַד יְיָ לְאִתְגַלָאָה לְמִפְרַק לֵהּ עַם מִגוֹ עַם בְּנִסִין בְּאָתִין וּבְמוֹפְתִין וּבִקְרָבָא וּבִידָא תַקִיפָא וּבִדְרָעָא מְרָמָא וּבְחֶזְוָנִין רַבְרְבִין כְּכֹל דִי עֲבַד לְכוֹן יְיָ אֱלָהֲכוֹן בְּמִצְרַיִם לְעֵינָיךְ:
@42 אַתְּ אִתְחֲזֵיתָא לְמִדַע אֲרֵי יְיָ הוּא אֱלֹהִים לֵית עוֹד בַּר מִנֵהּ:
@43 מִן שְׁמַיָא אַשְׁמְעָךְ יָת קָל מֵימְרֵהּ לְאַלָפוּתָךְ וְעַל אַרְעָא אַחְזְיָךְ יָת אֶשָׁתֵהּ רַבְּתָא וּפִתְגָמוֹהִי שְׁמַעַתְּ מִגוֹ אֶשָׁתָא:
@44 וָחֳלַף אֲרֵי רְחִים יָת אֲבָהָתָךְ וְאִתִּרְעֵי בִּבְנוֹהִי בַּתְרוֹהִי וְאַפְּקָךְ בְּמֵימְרֵהּ בְּחֵילֵהּ רַבָּא מִמִצְרָיִם:
@45 לְתָרָכָא עַמְמִין רַבְרְבִין וְתַקִיפִין מִנָךְ מִן קֳדָמָךְ לְאָעָלוּתָךְ לְמִתַּן לָךְ יָת אַרְעֲהוֹן אַחֲסָנָא כְּיוֹמָא הָדֵין:
@46 וְתִדַע יוֹמָא דֵין וּתְתוּב לְלִבָּךְ אֲרֵי יְיָ הוּא אֱלָהָא דִשְׁכִנְתֵּהּ בִּשְׁמַיָא מִ לְעֵלָא וְשַׁלִיט עַל אַרְעָא מִלְרָע לֵית עוֹד:
@47 וְתִטַר יָת קְיָמוֹהִי וְיָת פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין דִי יֵיטַב לָךְ וְלִבְנָיךְ בַּתְרָךְ וּבְדִיל דְתוֹרִיךְ יוֹמִין עַל אַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ כָּל יוֹמַיָא:
@48 בְּכֵן יַפְרֵשׁ מֹשֶׁה תְּלַת קִרְוִין בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@49 לְמֵעִירוֹק תַּמָן קָטוֹלָא דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵי וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקַמוֹהִי וְיֵעִרוֹק לְחַד מִן קִרְוַיָא הָאִלֵין וְיִתְקַיָם:
@50 יָת בֶּצֶר בְּמַדְבְּרָא בְּאַרְעָא מֵישְׁרָא לְשִׁבְטָּא דִרְאוּבֵן וְיָת רָאמוֹת בַּגִלְעָד לְשִׁבְטָא דְגָד וְיָת גוֹלָן בְּמַתְנָן לְשִׁבְטָא דִמְנַשֶׁה:
@51 וְדָא אוֹרַיְתָא דִי סַדַר מֹשֶׁה קֳדָם בְּנֵי יִשְׂרָאֵל:
@52 אִלֵין סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי מַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@53 בְּעִבְרָא דְיַרְדְנָא בְּחֵילָתָא לָקֳבֵל בֵּית פְּעוֹר בְּאַרְעָא דְסִיחֹן מַלְכָּא דֶאֱמֹרָאָה דִי יָתֵב בְּחֶשְׁבּוֹן דִי מְחָא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל בְּמִפָּקְהוֹן מִמִצְרָיִם:
@54 וִירִיתוּ יָת אַרְעֵהּ וְיָת אַרְעָא דְעוֹג מַלְכָּא דְמַתְנָן תְּרֵין מַלְכֵי אֱמֹרָאָה דִי בְּעִבְרָא דְיַרְדְנָא מִדְנַח שִׁמְשָׁא:
@55 מֵעֲרֹעֵר דִי עַל כֵּיף נַחֲלָא דְאַרְנֹן וְעַד טוּרָא דְשִׂיאֹן הוּא חֶרְמוֹן:
@56 וְכָל מֵישְׁרָא עִבְרָא דְיַרְדְנָא לְמָדִינְחָא וְעַד יַמָא דְמֵישְׁרָא תְּחוֹת מַשְׁפַּךְ מְרָמָתָא:
@57 וּקְרָא מֹשֶׁה לְכָל יִשְׂרָאֵל וַאֲמַר לְהוֹן שְׁמַע יִשְׂרָאֵל יָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְמַלֵל קֳדָמֵיכוֹן יוֹמָא דֵין וְתַלְפוּן יָתְהוֹן וְתִטְרוּן לְמֶעְבָּדְהוֹן:
@58 יְיָ אֱלָהָנָא גְזַר עִמָנָא קְיָם בְּחֹרֵב:
@59 לָא עִם אֲבְהָתָנָא גְזַר יְיָ יָת קְיָמָא הָדָא אֶלָהֵן עִמָנָא אֲנַחְנָא אִלֵין הָכָא יוֹמָא דֵין כֻּלָנָא קַיָמִין:
@60 מַמְלָל עִם מַמְלָל מַלִיל יְיָ עִמְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא:
@61 אֲנָא הֲוֵיתִי קָאֵם בֵּין מֵימְרָא דַיְיָ וּבֵינֵיכוֹן בְּעִדָנָא הַהִיא לְחַוָאָה לְכוֹן יָת פִּתְגָמָא דַיְיָ אֲרֵי דְחֶלְתּוּן מִקֳדָם אֵשָׁתָא וְלָא סְלֶקְתּוּן בְּטוּרָא לְמֵימָר:
@62 אֲנָא יְיָ אֱלָהָךְ דִי אַפֵּקְתָּךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עֲבְדוּתָא:
@63 לָא יְהֵא לָךְ אֱלָהּ אָחָרָן בַּר מִנִי:
@64 לָא תַעְבֵּד לָךְ צֶלֶם כָּל דְמוּת דִי בִשְׁמַיָא מִלְעֵלָא וְדִי בְאַרְעָא מִלְרָע וְדִי בְמַיָא מִלְרַע לְאַרְעָא:
@65 לָא תִסְגוּד לְהוֹן וְלָא תִפְלְחִנוּן אֲרֵי אֲנָא יְיָ אֱלָהָךְ אֵל קַנָא מַסְעַר חוֹבֵי אֲבָהָן עַל בְּנִין מְרָדִין עַל דַר תְּלִיתַי וְעַל דַר רְבִיעַי לְשַׂנְאָי כַּד מְשַׁלְמִין בְּנַיָא לְמֶחֱטֵּי בָּתַר אֲבָהָתְהוֹן:
@66 וְעָבֵד טֵּיבוּ לְאַלְפֵי דָרִין לְרַחֲמַי וּלְנָטְּרֵי פִקוֹדָי:
@67 לָא תֵימֵי בִּשְׁמָא דַיְיָ אֱלָהָךְ לְמַגָנָא אֲרֵי לָא יְזַכֵּי יְיָ יָת דִי יֵמֵי בִשְׁמֵהּ לְשִׁקְרָא:
@68 טַר יָת יוֹמָא דְשַׁבְּתָא לְקַדָשׁוּתֵהּ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@69 שִׁתָּא יוֹמִין תִּפְלָח וְתַעְבֵּד כָּל עִבִדְתָּךְ:
@70 וְיוֹמָא שְׁבִיעָאָה שַׁבְּתָא קֳדָם יְיָ אֱלָהָךְ לָא תַעְבֵּד כָּל עֲבִידָא אַתְּ וּבְרָךְ וּבְרַתָּךְ וְעַבְדָךְ וְאַמְתָךְ וְתוֹרָךְ וַחֲמָרָךְ וְכָל בְּעִירָךְ וְגִיוֹרָךְ דִי בְקִרְוָךְ בְּדִיל דִי יְנוּחַ עַבְדָךְ וְאַמְתָךְ כְּוָתָךְ:
@71 וְתִדְכַּר אֲרֵי עַבְדָא הֲוֵיתָא בְּאַרְעָא דְמִצְרַיִם וְאַפְּקָךְ יְיָ אֱלָהָךְ מִתַּמָן בִּידָא תַקִיפָא וּבִדְרָעָא מְרָמְמָא עַל כֵּן פַּקְדָךְ יְיָ אֱלָהָךְ לְמֶעְבַּד יָת יוֹמָא דְשַׁבְּתָא:
@72 יַקַר יָת אֲבוּךְ וְיָת אִמָךְ כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ בְּדִיל דְיוֹרְכוּן יוֹמָיךְ וּבְדִיל דְיֵיטַב לָךְ עַל אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@73 לָא תִקְטוֹל נְפָשׁ וְלָא תְגוּף וְלָא תִגְנוֹב (נַפְשָׁא) וְלָא תַסְהֵד בְּחַבְרָךְ סַהֲדוּתָא דְשִׁקְרָא:
@74 וְלָא תַחְמֵד אִתַּת חַבְרָךְ וְלָא תֵרוֹג בֵּית חַבְרָךְ חַקְלֵהּ וְעַבְדֵהּ וְאַמְתֵהּ תּוֹרֵה וַחֲמָרֵהּ וְכֹל דִי לְחַבְרָךְ:
@75 יָת פִּתְגָמַיָא הָאִלֵין מַלִיל יְיָ עִם כָּל קְהָלְכוֹן בְּטוּרָא מִגוֹ אֶשָׁתָא עֲנָנָא וַאֲמִיטְתָא קָל רַב וְלָא פְסַק וּכְתָבִנוּן עַל תְּרֵין לוּחֵי אַבְנַיָא וִיהָבִנָן לִי:
@76 וַהֲוָה כַּד שְׁמַעֲכוֹן יָת קָלָא מִגוֹ חֲשׁוֹכָא וְטוּרָא בָּעֵר בְּאֶשָׁתָא וְקָרֶבְתּוּן לְוָתִי כָּל רֵישֵׁי שִׁבְטֵיכוֹן וְסָבֵיכוֹן:
@77 וַאֲמַרְתּוּן הָא אַחְזְיָנָא יְיָ אֱלָהָנָא יָת יְקָרֵהּ וְיָת רְבוּתֵהּ וְיָת קָל מֵימְרֵהּ שְׁמַעְנָא מִגוֹ אֶשָׁתָא יוֹמָא הָדֵין חֲזֵינָא אֲרֵי יְמַלֵל יְיָ עִם אֲנָשָׁא וְיִתְקַיָם:
@78 וּכְעַן לְמָא נְמוּת אֲרֵי תֵיכְלִנָנָא אֶשָׁתָא רַבְּתָא הָדָא אִם מוֹסְפִין אֲנַחְנָא לְמִשְׁמַע יָת קָל מֵימְרָא דַייָ אֱלָהָנָא עוֹד וּמָיְתִין אֲנַחְנָא:
@79 אֲרֵי מָן כָּל בִּשְׂרָא דִי שְׁמַע קָל מֵימְרָא דַיְיָ קַיָמָא מְמַלֵל מִגוֹ אֶשָׁתָא כְּוָתָנָא וְאִתְקַיָם:
@80 קְרַב אַתְּ וּשְׁמַע יָת כָּל דִי יֵימַר יְיָ אֱלָהָנָא וְאַתְּ תְּמַלֵל עִמָנָא יָת כָּל דִי מַלֵל יְיָ אֱלָהָנָא עִמָךְ וּנְקַבֵּל וְנַעְבֵּד:
@81 וּשְׁמִיעַ קֳדָם יְיָ יָת קָל פִּתְגָמֵיכוֹן בְּמַלָלוּתְכוֹן עִמִי וַאֲמַר יְיָ לִי שְׁמִיעַ קֳדָמַי יָת קָל פִּתְגָמֵי עַמָא הָדֵין דִי מַלִילוּ עִמָךְ אַתְקִינוּ כָּל דִי מַלִילוּ:
@82 לְוַי דִי יְהֵי לִבָּא הָדֵין לְהוֹן לְמִדְחַל קֳדָמַי וּלְמִטַר יָת כָּל פִּקוּדַי כָּל יוֹמַיָא בְּדִיל דִיֵיטַב לְהוֹן וְלִבְנֵיהוֹן לְעָלָם:
@83 אִזֵל אֱמַר לְהוֹן תּוּבוּ לְכוֹן לְמַשְׁכְּנֵיכוֹן:
@84 וְאַתְּ הָכָא קִים קֳדָמַי וֶאֱמַלֵל עִמָךְ יָת כָּלּ תַּפְקֶדְתָּא וּקְיָמַיָא וְדִינַיָא דִי תַלְפִנוּן וְיַעְבְּדוּן בְּאַרְעָא דִי אֲנָא יָהֵב לְהוֹן לְמֵירְתַהּ:
@85 וְתִטְרוּן לְמֶעְבַּד כְּמָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן לָא תִסְטוּן יַמִינָא וּשְׂמָאלָא:
@86 בְּכָל אָרְחָא דִי פַקִיד יְיָ אֱלָהֲכוֹן יָתְכוֹן תְּהָכוּן בְּדִיל דְתֵיחוּן וְיֵיטַב לְכוֹן וְתוֹרְכוּן יוֹמִין בְּאַרְעָא דִי תֵירְתוּן:
@87 וְדָא תַפְקֶדְתָּא קְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהֲכוֹן לְאַלָפָא יָתְכוֹן לְמֶעְבַּד בְּאַרְעָא דִי אַתּוּן עָבְרִין תַּמָן לְמֵירְתַהּ:
@88 בְּדִיל דְתִדְחַל קֳדָם יְיָ אֱלָהָךְ לְמִטַר יָת כָּל קְיָמוֹהִי וּפִקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ אַתְּ וּבְרָךְ וּבַר בְּרָךְ כָּל יוֹמֵי חַיָיךְ וּבְדִיל דְיוֹרְכוּן יוֹמָיךְ:
@89 וּתְקַבֵּל יִשְׂרָאֵל וְתִטַר לְמֶעְבַּד דִי יֵיטַב לָךְ וְדִי תִסְגוּן לַחֲדָא כְּמָא דִי מַלִיל יְיָ אֱלָהָא דַאֲבָהָתָךְ לָךְ אַרְעָא עָבְדָא חֲלַב וּדְבָשׁ:
@90 שְׁמַע יִשְׂרָאֵל יְיָ אֱלָהָנָא יְיָ חָד:
@91 וְתִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ וּבְכָל נִכְסָךְ:
@92 וִיהוֹן פִּתְגָמַיָא הָאִלֵין דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין עַל לִבָּךְ:
@93 וּתְתָנִנוּן לִבְנָיךְ וּתְמַלֵל בְּהוֹן בְּמִתְּבָךְ בְּבֵיתָךְ וּבִמְהָכָךְ בְּאָרְחָא וּבְמִשְׁכְּבָךְ וּבִמְקִימָךְ:
@94 וְתִקְטְרִנוּן לְאָת עַל יְדָךְ וִיהוֹן לִתְפִלִין בֵּין עֵינָיךְ:
@95 וְתִכְתְּבִנוּן עַל מְזוּזְיָן וְתִקְבְּעִנוּן בְּסִפֵּי בֵיתָךְ וּבְתַרְעָיךְ:
@96 וִיהֵי אֲרֵי יָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לָךְ קִרְוִין רַבְרְבָן וְטָבָן דִי לָא בְנֵיתָא:
@97 וּבָתִּין מְלָן כָּל טוּב דִי לָא מְלֵיתָא וְגֻבִּין פְּסִילָן דִי לָא פְּסַלְתָּא כַּרְמִין וְזֵיתִין דִי לָא נְצֶבְתָּא וְתֵיכוּל וְתִשְׂבָּע:
@98 אִסְתַּמַר לָךְ דִילְמָא תִנְשֵׁי יָת (דַחַלְתָּא דַ) יְיָ דִי אַפְּקָךְ מֵאַרְעָא דְמִצְרַיִם מִבֵּית עַבְדוּתָא:
@99 יָת יְיָ אֱלָהָךְ תִּדְחַל וְקָדָמוֹהִי תִּפְלָח וּבִשְׁמֵהּ תְּקַיַם:
@100 לָא תְהָכוּן בָּתַר טַעֲוַת עַמְמַיָא מִטַעֲוַת עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן:
@101 אֲרֵי אֵל קַנָא יְיָ אֱלָהָךְ שְׁכִנְתֵּהּ בֵּינָךְ דִילְמָא יִתְקֵף רָגְזָא דַיְיָ אֱלָהָךְ בָּךְ וִישֵׁצָךְ מֵעַל אַפֵּי אַרְעָא:
@102 לָא תְנַסוּן קֳדָם יְיָ אֱלָהֲכוֹן כְּמָא דִי נַסֵתוּן בְנִסֵיתָא:
@103 מִטַּר תִּטְרוּן יָת פִּקוּדַיָא דַיְיָ אֱלָהֲכוֹן וּסְהֶדְוָתֵהּ וּקְיָמוֹהִי דִי פַקְדָךְ:
@104 וְתַעְבֵּד דְכָשַׁר וּדְתַקֵן קֳדָם יְיָ בְּדִיל דְיֵיטַב לָךְ וְתֵעוּל וְתֵירַת יָת אַרְעָא טַבְתָא דִי קַיִים יְיָ לַאֲבָהָתָךְ:
@105 לְמִתְּבַר יָת כָּל בַּעֲלֵי דְבָבָךְ מֵקָדָמָךְ כְּמָא דִי מַלִיל יְיָ:
@106 אֲרֵי יִשְׁאֲלִנָךְ בְּרָךְ מְחָר לְמֵימָר מָא סָהֶדְוָתָא וּקְיָמַיָא וְדִינַיָא דִי פַקִיד יְיָ אֱלָהָנָא יָתְכוֹן:
@107 וְתֵימַר לִבְרָךְ עַבְדִין הֲוֵינָא לְפַרְעֹה בְּמִצְרָיִם וְאַפְּקָנָא יְיָ מִמִצְרַיִם בִּידָא תַקִיפָא:
@108 וִיהַב יְיָ אָתִין וּמוֹפְתִין רַבְרְבִין וּבִישִׁין בְּמִצְרַיִם בְּפַרְעֹה וּבְכָל אֱנַשׁ בֵּיתֵהּ לְעֵינָנָא:
@109 וְיָתָנָא אַפֵּק מִתַּמָן בְּדִיל לְאַעֲלָא יָתָנָא לְמִתַּן לָנָא יָת אַרְעָא דִי קַיִים לַאֲבָהָתָנָא:
@110 וּפַּקְדָנָא יְיָ לְמֶעְבַּד יָת כָּל קְיָמַיָא הָאִלֵין לְמִדְחַל יָת יְיָ אֱלָהָנָא לְטַב לָנָא כָּל יוֹמַיָא לְקַיָמוּתָנָא כְּיוֹמָא הָדֵין:
@111 וְזָכוּתָא תְּהֵא לָנָא אֲרֵי נִטַר לְמֶעְבַּד יָת כָּל תַּפְקֶדְתָּא הָדָא קֳדָם יְיָ אֱלָהָנָא כְּמָא דִי פַקְדָנָא:
@112 אֲרֵי יְעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ וִיתָרֵךְ עַמְמִין סַגִיאִין מִן קֳדָמָךְ חִתָּאֵי וְגִרְגָשָׁאֵי וֶאֱמֹרָאֵי וּכְנַעֲנָאֵי וּפְרִזָאֵי וְחִוָאֵי וִיבוּסָאֵי שִׁבְעָא עַמְמִין סַגִיאִין וְתַקִיפִין מִנָךְ:
@113 וְיִמְסְרִנוּן יְיָ אֱלָהָךְ קֳדָמָךְ וְתִמְחִנוּן גַמָרָא תְגַמַר יָתְהוֹן לָא תִגְזַר לְהוֹן קְיָם וְלָא תְרַחַם עֲלֵיהוֹן:
@114 וְלָא תִתְחַתַּן בְּהוֹן בְּרַתָּךְ לָא תִתֵּן לִבְרֵהּ וּבְרַתֵּהּ לָא תִסַב לִבְרָךְ:
@115 אֲרֵי יַטְעֲיַן יָת בְּרָךְ מִבָּתַר פָּלְחָנִי וְיִפְלְחוּן לְטַעֲוַת עַמְמַיָא וְיִתְקֵף רָגְזָא דַיְיָ בְּכוֹן וִישֵׁצָךְ בִּפְרִיעַ:
@116 אֲרֵי אִם כְּדֵין תַּעַבְּדוּן לְהוֹן אֱגוֹרֵיהוֹן תְּתָרְעוּן וְקָמָתְהוֹן תְּתַבְּרוּן וַאֲשֵׁרֵיהוֹן תְּקוֹצְצוּן וְצַלְמֵי טַּעֲוָתְהוֹן תּוֹקְדוּן בְּנוּרָא:
@117 אֲרֵי עַם קַדִישׁ אַתְּ קֳדָם יְיָ אֱלָהָךְ בָּךְ אִתִּרְעֵי יְיָ אֱלָהָךְ לְמֶהֱוֵי לֵהּ לְעַם חַבִּיב מִכֹּל עַמְמַיָא דִי עַל אַפֵּי אַרְעָא:
@118 לָא מִדְסַגִיאִין אַתּוּן מִכָּל עַמְמַיָא צָבֵי יְיָ בְּכוֹן וְאִתִּרְעֵי בְכוֹן אֲרֵי אַתּוּן זְעֵרִין מִכָּל עַמְמַיָא:
@119 אֲרֵי מִדְרַחַם יְיָ יָתְכוֹן וּמִדִנְטַר יָת קְיָמָא דִי קַיִים לַאֲבָהָתְכוֹן אַפֵּיק יְיָ יָתְכוֹן בִּידָא תַקִיפָא וּפָרְקָךְ מִבֵּית עַבְדוּתָא מִידָא דְפַרְעֹה מַלְכָּא דְמִצְרָיִם:
@120 וְתִדַע אֲרֵי יְיָ אֱלָהָךְ הוּא אֱלֹהִים אֱלָהָא מְהֵימְנָא נָטֵר קְיָמָא וְחִסְדָא לְרַחֲמוֹהִי וּלְנָטְרֵי פִקוֹדוֹהִי לְאַלְפֵי דָרִין:
@121 וּמְשַׁלֵם לְסָנְאוֹהִי טָבָן דִי אִנוּן עָבְדִין קֳדָמוֹהִי בְּחַיֵיהוֹן לְאוֹבָדֵיהוֹן לָא מְאַחַר עֹבַד טָב לְסָנְאוֹהִי טַבְוָן דִי אִנוּן עָבְדִין קָדָמוֹהִי בְּחַיֵיהוֹן מְשַׁלֵם לְהוֹן:
@122 וְתִטַר יָת תַּפְקֶדְתָּא וְיָת קְיָמַיָא וְיָת דִינַיָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמֶעְבָּדְהוֹן: פפפ:

@1 **ואתחנן.** אין חנון בכל מקום אלא לשון מתנת חנם. אף על פי שיש להם לצדיקים לתלות במעשיהם הטובים, אין מבקשים מאת המקום אלא מתנת חנם. לפי שאמר לו (שמות לג, יט) וחנתי את אשר אחן, אמר לו בלשון ואתחנן. דבר אחר זה אחד מעשרה לשונות שנקראת תפלה, כדאיתא בספרי: **בעת ההיא.** לאחר שכבשתי ארץ סיחון ועוג דמיתי שמא התר הנדר: **לאמר.** זה אחד משלשה מקומות שאמר משה לפני המקום איני מניחך עד שתודיעני אם תעשה שאלתי אם לאו:
@2 **ה' אלהים.** רחום בדין: **אתה החלות להראות את עבדך.** פתח להיות עומד ומתפלל, אף על פי שנגזרה גזרה. אמר לו ממך למדתי, שאמרת לי (שמות לב, י) ועתה הניחה לי, וכי תופס הייתי בך, אלא לפתוח פתח, שבי תלוי להתפלל עליהם, כמו כן הייתי סבור לעשות עכשיו: **את גדלך.** זו מדת טובך וכן הוא אומר (במדבר יד, יז) ועתה יגדל נא כח ה': **ואת ידך.** זו ימינך, שהיא פשוטה לכל באי עולם: **החזקה.** שאתה כובש ברחמים את מדת הדין החזקה: **אשר מי אל** וגו' **.** אינך דומה למלך בשר ודם, שיש לו יועצין וסנקתדרין הממחין בידו כשרוצה לעשות חסד ולעבור על מדותיו, אתה אין מי ימחה בידך אם תמחול לי ותבטל גזרתך. ולפי פשוטו אתה החלות להראות את עבדך מלחמת סיחון ועוג, כדכתיב (דברים ב, לא) ראה החלתי תת לפניך, הראני מלחמת שלשים ואחד מלכים:
@3 **אעברה נא.** אין נא אלא לשון בקשה: **ההר הטוב הזה.** זו ירושלים: **והלבנון.** זה בית המקדש:
@4 **ויתעבר ה'.** נתמלא חמה: **למענכם.** בשבילכם, אתם גרמתם לי. וכן הוא אומר (תהלים קו, לב) ויקציפו על מי מריבה וירע למשה בעבורם: **רב לך.** שלא יאמרו הרב כמה קשה והתלמיד כמה סרבן ומפציר. דבר אחר רב לך הרבה מזה שמור לך, רב טוב הצפון לך:
@5 **וראה בעיניך.** בקשת ממני (פסוק כה) ואראה את הארץ הטובה, אני מראה לך את כלה שנאמר (דברים לד, א) ויראהו ה' את כל הארץ:
@6 **וצו את יהושע.** על הטרחות ועל המשאות ועל הריבות: **וחזקהו ואמצהו.** בדבריך, שלא ירך לבו לומר כשם שנענש רבי עליהם כך סופי לענש עליהם, מבטיחו אני כי הוא יעבור והוא ינחיל: **כי הוא יעבר.** אם יעבור לפניהם ינחלו, ואם לאו לא ינחלו. וכן אתה מוצא כששלח מן העם אל העי והוא ישב (יהושע ז, ה) ויכו מהם אנשי העי וגו' (שם ז, י) , וכיון שנפל על פניו אמר לו קום לך. קם לך כתיב, אתה הוא העומד במקומך ומשלח את בני למלחמה, למה זה אתה נפל על פניך, לא כך אמרתי למשה רבך אם הוא עובר, עוברין, ואם לאו, אין עוברין:
@7 **ונשב בגיא** וגו' **.** ונצמדתם לעבודה זרה ואף על פי כן (דברים ד, א) ועתה ישראל שמע אל החקים והכל מחול לך ואני לא זכיתי למחל לי:
@9 **לא תספו.** כגון חמש פרשיות בתפלין, חמשת מינין בלולב, וחמש ציציות, וכן ולא תגרעו:
@13 **ושמרתם.** זו משנה: **ועשיתם.** כמשמעו: **כי הוא חכמתכם ובינתכם** וגו' **.** בזאת תחשבו חכמים ונבונים לעיני העמים:
@15 **חקים ומשפטים צדיקם.** הגונים ומקבלים:
@16 **רק השמר לך** וגו' **פן תשכח את הדברים.** אז כשלא תשכחו אותם ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעותו אותם מתוך שכחה תחשבו שוטים:
@17 **יום אשר עמדת.** מוסב על מקרא שלמעלה ממנו אשר ראו עיניך, יום אשר עמדת בחורב אשר ראיתם את הקולות ואת הלפידים: **ילמדון.** ילפון, לעצמם: **ילמדון.** יאלפון, לאחרים:
@21 **ואתי צוה ה' בעת ההוא ללמד אתכם.** תורה שבעל פה:
@23 **סמל.** צורה:
@26 **ופן תשא עיניך.** להסתכל בדבר ולתת לב לשוב לטעות אחריהם: **אשר חלק** וגו' **לכל העמים.** להאיר להם. דבר אחר לאלהות. לא מנען מלטעות אחריהם, אלא החליקם בדברי הבליהם לטרדם מן העולם. וכן הוא אומר (תהלים לו, ג) כי החליק אליו בעיניו למצא עונו לשנא:
@27 **מכור.** הוא כלי שמזקקים בו את הזהב:
@28 **התאנף.** נתמלא רוגז: **על דבריכם.** על אודותיכם על עסקיכם:
@29 **כי אנכי מת** וגו' **אינני עבר.** מאחר שמת מהיכן יעבר, אלא אף עצמותי אינם עוברין:
@30 **תמונת כל.** תמונת כל דבר: **אשר צוך ה'.** אשר צוך עליו שלא לעשות:
@31 **אל קנא.** מקנא לנקום אנפרנמנ''ט בלע''ז [חמה] מתחרה על רגזו להפרע מעובדי עבודה זרה:
@32 **ונושנתם.** רמז להם שיגלו ממנה לסוף שמונה מאות וחמשים ושתים שנה, כמנין ונושנתם. והוא הקדים והגלם לסוף שמונה מאות וחמשים והקדים שתי שנים לונושנתם, כדי שלא יתקים בהם (פסוק כו) כי אבד תאבדון וזהו שנאמר (דניאל ט, יד) וישקד ה' על הרעה ויביאה עלינו כי צדיק ה' אלהינו, צדקה עשה עמנו שמהר להביאה שתי שנים לפני זמנה:
@33 **העידתי בכם.** הנני מזמינם להיות עדים שהתריתי בכם:
@35 **ועבדתם שם אלהים.** כתרגומו. משאתם עובדים לעובדיהם כאלו אתם עובדים להם:
@38 **לא ירפך.** מלהחזיק בך בידיו. ולשון לא ירפך לשון לא יפעיל הוא, לא יתן לך רפיון, לא יפריש אותך מאצלו. וכן אחזתיו ולא ארפנו (שה''ש ג ד) , שלא ננקד ארפנו. כל לשון רפיון מוסב על לשון מפעיל ומתפעל, כמו (מלכים ב' ד, כז) הרפה לה, תן לה רפיון (דברים ט, יד) הרף ממני, התרפה ממני:
@39 **לימים ראשונים.** על ימים ראשונים: **ולמקצה השמים.** וגם שאל לכל הברואים אשר מקצה אל קצה זהו פשוטו. ומדרשו, מלמד על קומתו של אדם שהיתה מן הארץ עד השמים והוא השעור עצמו אשר מקצה אל קצה: **הנהיה כדבר הגדול הזה.** ומהו הדבר הגדול, השמע עם וגו' :
@41 **הנסה אלהים.** הכי עשה נסים שום אלוה, **לבא לקחת לו גוי** וגו' **.** כל ההי''ן הללו תמיהות הן, לכך נקודות הן בחט''ף פת''ח, הנהיה, הנשמע, הנסה, השמע: **במסות.** על ידי נסיונות הודיעם גבורותיו, כגון (שמות ח, ה) התפאר עלי, אם אוכל לעשות כן, הרי זה נסיון: **באותות.** בסימנין להאמין שהוא שלוחו של מקום, כגון (שמות ד, ב) מה זה בידך: **ובמופתים.** הם נפלאות שהביא עליהם מכות מפלאות: **ובמלחמה.** בים, שנאמר (שם יד, כה) כי ה' נלחם להם:
@42 **הראת.** כתרגומו אתחזיתא. כשנתן הקדוש ברוך הוא את התורה פתח להם שבעה רקיעים. וכשם שקרע את העליונים כך קרע את התחתונים. וראו שהוא יחידי, לכך נאמר אתה הראת לדעת:
@44 **ותחת כי אהב.** וכל זה תחת אשר אהב: **ויוצאך בפניו.** כאדם המנהיג בנו לפניו שנאמר (שמות יד, יט) ויסע מלאך האלהים ההולך וגו' וילך מאחריהם. דבר אחר ויוצאך בפניו בפני אבותיו, כמו שנאמר (תהלים עח, יב) נגד אבותם עשה פלא. ואל תתמה על שהזכירם בלשון יחיד, שהרי כתבם בלשון יחיד ויבחר בזרעו אחריו:
@45 **ממך מפניך.** סרסהו ודרשהו להוריש מפניך גוים גדולים ועצומים ממך: **כיום הזה.** כאשר אתה רואה היום:
@48 **אז יבדיל.** נתן לב להיות חרד לדבר שיבדילם. ואף על פי שאינן קולטות עד שיבדלו אותן שבארץ כנען, אמר משה, מצוה שאפשר לקימה אקימנה: **בעבר הירדן מזרחה שמש.** באותו עבר שבמזרחו של ירדן: **מזרחה שמש.** לפי שהוא דבוק, נקודה רי''ש בחטף, מזרח של שמש, מקום זריחת השמש:
@51 **וזאת התורה.** זו שהוא עתיד לסדר אחר פרשה זו:
@52 **אלה העדת** וגו' **אשר דבר.** הם הם אשר דבר בצאתם ממצרים חזר ושנאה להם בערבות מואב:
@54 **אשר בעבר הירדן.** שהוא במזרח, שהעבר השני היה במערב:
@59 **לא את אבתינו.** בלבד **כרת ה'** וגו' **כי אתנו:**
@60 **פנים בפנים.** אמר ר' ברכיה, כך אמר משה אל תאמרו אני מטעה אתכם על לא דבר, כדרך שהסרסור עושה בין המוכר ללוקח, הרי המוכר עצמו מדבר עמכם:
@61 **לאמר.** מוסב על (פסוק ד) דבר ה' עמכם בהר מתוך האש לאמר אנכי ה' וגו' ואנכי עומד בין ה' וביניכם:
@63 **על פני.** בכל מקום אשר אני שם וזהו כל העולם. דבר אחר כל זמן שאני קים. עשרת הדברות כבר פרשתים:
@71 **שמור.** ובראשונות הוא אומר (שמות כ) זכור. שניהם בדבור אחד ובתיבה אחת נאמרו ובשמיעה אחת נשמעו: **כאשר צוך.** קודם מתן תורה במרה: **וזכרת כי עבד היית** וגו' **.** על מנת כן פדאך שתהיה לו עבד ותשמר מצותיו:
@72 **כאשר צוך.** אף על כבוד אב ואם נצטוו במרה שנאמר (שמות טו, כה) שם שם לו חק ומשפט:
@73 **ולא תנאף.** אין לשון נאוף אלא באשת איש:
@74 **ולא תתאוה.** לא תרוג אף הוא לשון חמדה, כמו (בראשית ב, ט) נחמד למראה, דמתרגמנן דמרגג למחזי:
@75 **ולא יסף.** מתרגמנן ולא פסק. כי קולו חזק וקים לעולם. דבר אחר, ולא יסף, לא הוסיף להראות באותו פומבי:
@80 **ואת תדבר אלינו.** התשתם את כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כי ראיתי שאינכם חרדים להתקרב אליו מאהבה. וכי לא היה יפה לכם ללמוד מפי הגבורה ולא ללמוד ממני:
@90 **ה' אלהינו ה' אחד.** ה' שהוא אלהינו עתה ולא אלהי האמות, הוא עתיד להיות ה' אחד, שנאמר (צפניה ג, ט) כי אז אהפך אל עמים שפה ברורה לקרא כלם בשם ה' ונאמר (זכריה יד, ט) ביום ההוא יהיה ה' אחד ושמו אחד:
@91 **ואהבת.** עשה דבריו מאהבה. אינו דומה עושה מאהבה לעושה מיראה. העושה אצל רבו מיראה כשהוא מטריח עליו מניחו והולך לו: **בכל לבבך.** בשני יצריך. דבר אחר בכל לבבך, שלא יהיה לבך חלוק על המקום: **ובכל נפשך.** אפלו הוא נוטל את נפשך: **ובכל מאדך.** בכל ממונך יש לך אדם שממונו חביב עליו מגופו לכך נאמר ובכל מאדך. דבר אחר ובכל מאדך בכל מדה ומדה שמודד לך בין במדה טובה בין במדת פרענות וכן דוד הוא אומר (תהלים קטז, יג) כוס ישועות אשא וגו' (שם קטז, יג) צרה ויגון אמצא וגו' :
@92 **והיו הדברים האלה.** ומהו האהבה והיו הדברים האלה, שמתוך כך אתה מכיר בהקדוש ברוך הוא ומדבק בדרכיו: **אשר אנכי מצוך היום.** לא יהיו בעיניך כדיוטגמא ישנה שאין אדם סופנה, אלא כחדשה שהכל רצין לקראתה. דיוטגמא, מצות המלך הבאה במכתב:
@93 **ושננתם.** לשון חדוד הוא, שיהיו מחדדים בפיך, שאם ישאלך אדם דבר לא תהא צריך לגמגם בו, אלא אמור לו מיד: **לבניך.** אלו התלמידים. מצינו בכל מקום שהתלמידים קרויים בנים, שנאמר (דברים יד, א) בנים אתם לה' אלהיכם, ואומר (מלכים ב' ב, ג) בני הנביאים אשר בבית אל, וכן בחזקיהו שלמד תורה לכל ישראל וקראם בנים שנאמר (ד''ה ב' כט, יא) בני עתה אל תשלו. וכשם שהתלמידים קרויים בנים, שנאמר בנים אתם לה' אלהיכם, כך הרב קרוי אב, שנאמר (מלכים ב' ב) אבי אבי רכב ישראל וגו' : **ודברת בם.** שלא יהא עיקר דבורך אלא בם. עשם עיקר ואל תעשם טפל: **ובשכבך.** יכול אפלו שכב בחצי היום, תלמוד לומר ובקומך. יכול אפלו עמד בחצי הלילה, תלמוד לומר בשבתך בביתך ובלכתך בדרך. דרך ארץ דברה תורה, זמן שכיבה וזמן קימה:
@94 **וקשרתם לאות על ידך.** אלו תפלין שבזרוע: **והיו לטטפת בין עיניך.** אלו תפלין שבראש ועל שם מנין פרשיותיהם נקראו טטפת. טט בכתפי שתים, פת באפריקי שתים:
@95 **מזזות ביתך.** מזוזת כתיב, שאין צריך אלא אחת: **ובשעריך.** לרבות שערי חצרות ושערי מדינות ושערי עירות:
@97 **חצובים.** לפי שהיו מקום טרשין וסלעים נופל בו לשון חציבה:
@98 **מבית עבדים.** כתרגומו מבית עבדותא, ממקום שהייתם שם עבדים:
@99 **ובשמו תשבע.** אם יש בך כל המדות הללו, שאתה ירא את שמו ועובד אותו, אז בשמו תשבע, שמתוך שאתה ירא את שמו תהא זהיר בשבועתך, ואם לאו לא תשבע:
@100 **מאלהי העמים אשר סביבותיכם.** הוא הדין לרחוקים, אלא לפי שאתה רואה את סביבותיך תועים אחריהם הצרך להזהיר עליהם ביותר:
@102 **במסה.** כשיצאו ממצרים שנסוהו במים, שנאמר (שמות יז, ז) היש ה' בקרבנו:
@104 **הישר והטוב.** זו פשרה, לפנים משורת הדין:
@105 **כאשר דבר.** והיכן דבר (שמות כג, כז) והמתי את כל העם וגו' :
@106 **כי ישאלך בנך מחר.** יש מחר שהוא אחר זמן:
@112 **ונשל.** לשון השלכה והתזה, וכן (דברים יט, ה) ונשל הברזל:
@113 **לא תחנם.** לא תתן להם חן. אסור לו לאדם לומר כמה נאה גוי זה. דבר אחר אל תתן להם חניה בארץ:
@115 **כי יסיר את בנך מאחרי.** בנו של גוי כשישא את בתך, יסיר את בנך אשר תלד לו בתך מאחרי. למדנו שבן בתך הבא מן הגוי קרוי בנך, אבל בן בנך הבא מן הגויה אינו קרוי בנך אלא בנה, שהרי לא נאמר על בתו לא תקח כי תסיר את בנך מאחרי:
@116 **מזבחתיהם.** של בנין: **מצבותם.** אבן אחת: **ואשירהם.** אילנות שעובדין אותן: **ופסיליהם.** צלמים:
@118 **לא מרבכם.** כפשוטו. ומדרשו לפי שאין אתם מגדילים עצמכם כשאני משפיע לכם טובה לפיכך חשקתי בכם: **כי אתם המעט.** הממעטין עצמכם, כגון אברהם, שאמר (בראשית יח, כז) ואנכי עפר ואפר, וכגון משה ואהרן שאמרו (שמות טז, ח) ונחנו מה, לא כנבוכדנצר שאמר (ישעיה יד, יד) אדמה לעליון, וסנחריב שאמר (שם לו, כ) מי בכל אלהי הארצות, וחירם שאמר (יחזקאל כח, ב) אל אני מושב אלהים ישבתי: **כי אתם המעט.** הרי כי משמש בלשון דהא:
@119 **כי מאהבת ה'.** הרי כי משמש בלשון אלא. לא מרבכם חשק ה' בכם, אלא מאהבת ה' אתכם: **ומשמרו את השבועה.** מחמת שמרו את השבועה:
@120 **לאלף דור.** ולהלן הוא אומר (דברים ה, ט) לאלפים, כאן שהוא סמוך אצל לשומרי מצותיו, העושין מיראה, הוא אומר לאלף, ולהלן שהוא סמוך אצל לאוהביו, העושין מאהבה, ששכרם יותר גדול, הוא אומר לאלפים: **לאוהביו.** אלו העושין מאהבה: **ולשומרי מצותיו.** אלו העושין מיראה:
@121 **ומשלם לשנאיו אל פניו.** בחייו משלם לו גמולו הטוב כדי להאבידו מן העולם הבא:
@122 **היום לעשותם.** ולמחר לעולם הבא לטול שכרם:

@1 **ואתחנן אל ה' בעת ההוא לאמר** . כאשר הזכיר כבוש ארץ סיחון ועוג ואמר (לעיל פסוק כא) ואת יהושע צויתי בעת ההיא הזכיר כי אני לא אעבור שם כי התחננתי אל השם הנכבד ולא שמע אלי וצוה אותי לחזק את יהושע כי הוא יעבור וטעם בעת ההיא רמז לעת הגזרה שהזכיר (לעיל א לז) גם בי התאנף ה' ולא נזכרה שם התחנה ביום המעשה והנכון כי "בעת ההיא" בעת הנזכרת שכבשתי סיחון ועוג והתחלתי להלחם בעממין שניתנו לישראל וחלקתי הארץ לשני השבטים והיה זה כאשר נאמר לו (במדבר כז יב) עלה אל הר העברים הזה כי אז בקש רחמים על הדבר והתחנן התחנה הזאת וכאשר לא שמע השם בקולו חזר והתפלל יפקוד ה' אלהי הרוחות לכל בשר איש על העדה כמו שנזכר שם (פסוק טז) וזהו וצו את יהושע (להלן פסוק כח) אבל הזכיר שם התפלה אשר נענה עליה וכאן הזכיר זה להודיע כי הארץ היתה חביבה עליו מאד ולא זכה אליה בעבורם וכל זה מתוכחותיו
@2 **ה' אלהים** . רחום בדין לשון רש"י ולא השגיח הרב כי השם הראשון הוא כתוב באל"ף דל"ת והשני הוא כתוב ביו"ד ה"א שבו אמרו כל מקום שנאמר ה' זו מדת רחמים אלהים זו מדת הדין אבל השמות הנזכרים כאן אדון במדת רחמים וכך אמרו בילמדנו אמר לו רבון העולמים אי מתבעי לי בדין הב לי ואי לא מתבעי לי בדין רחם עלי כשם שאמר אברהם ה' אלהים מה תתן לי וגו' וגם באברהם כך הם כתובים הראשון אל"ף דל"ת והשני יו"ד ה"א וענין הפרשה יובן בזה כי אמר "ואתחנן" ולא אמר "ואתפלל" כי ידבר בתחנה ואמר אדון אשר בך הרחמים אתה החלות להראות את עבדך כך היא תחלת נבואתי שהראית לי כבודך דכתיב ויסתר משה פניו כי ירא מהביט אל האלהים (שמות ג ו) עם הגדולה והגבורה והראיתי לדעת מי אל בשמים ובארץ שממנו יהיו כמעשיך הגדולים וכגבורותיך החזקות ומכאן תבין עוד במה התאנף בו השם הנכבד אבל לשון ספרי (ואתחנן כד) כל מקום שנאמר ה' זו מדת רחמים שנאמר ה' אל רחום וחנון אלהים זו היא מדת הדין שנאמר עד האלהים יבוא דבר שניהם והכוונה לפרש כי השם השני בכאן הוא מדת הרחמים והוא השם המיוחד ושאר השמות כולן מדת הדין כמו אלהים שהוא שם גם לדיינים וכל שכן אל"ף דל"ת שהוא לשון אדונים והנה השלים התוכחות בזה שהודיע אותם שגרמו אבותיהם רעה על עצמם וגם עליו גרמו עונש שלא יעברו לארץ אבל הם הבנים יעברו ויירשו אותה אם לא יהיו כאבותם דור סורר ומורה ולכך יתחיל עתה להזהירם בכללי המצות שלא יוסיפו עליהם ולא יגרעו מהם
@9 **לא תוסיפו** . כגון חמש פרשיות בתפילין חמשה מינין בלולב חמש ציציות וכן לא תגרעו לשון רש"י וכך אמרו בספרי (ראה) מנין שלא תוסיף על הלולב ועל הציצית ת"ל לא תוסיפו ומנין שאין פוחתים מהן ת"ל לא תגרעו מנין שאם פתח לברך ברכת כהנים לא יאמר הואיל ופתחתי לברך אומר ה' אלהי אבותיכם יוסף עליכם ת"ל הדבר אפילו דבר לא תוסף עליו אבל לא באלה בלבד אמרו אלא אף הישן בסוכה בשמיני בכונה לוקה כמו שמוזכר במסכת ראש השנה (כח) וכן אם יעשה החג ששה עובר בלאו הזה ולפי דעתי אפילו בדא לעשות מצוה בפני עצמה כגון שעשה חג בחדש שבדא מלבו כירבעם (מלכים א יב לג) עובר בלאו וכך אמרו (מגילה יד) לענין מקרא מגלה מאה ושמונים נביאים עמדו להם לישראל ולא פחתו ולא הוסיפו על מה שכתוב בתורה אפילו אות אחת חוץ ממקרא מגילה מאי דרוש וכו' ובירושלמי (מגילה פ"א ה"ז) שמונים וחמשה זקנים ומהם כמה נביאים היו מצטערים על הדבר אמרו כתוב אלה המצות אשר צוה ה' את משה אלו המצות שנצטוו מפי משה כך אמר לנו משה ואין נביא אחר עתיד לחדש דבר לכם ומרדכי ואסתר רוצים לחדש לנו דבר לא זזו משם נושאין ונותנין בדבר עד שהאיר הקב"ה עיניהם וכו' הרי שהיתה המצוה הזו אסורה להם א"כ היא בכלל לא תוסיף עליו אלא שלא למדנו למוסיף על פי נביא אלא מן הכתוב שאמר "אלה המצות" אין נביא רשאי לחדש בו דבר מעתה ומה שתקנו חכמים משום גדר כגון שניות לעריות וכיוצא בהן זו היא מצוה מן התורה ובלבד שידע שהם משום הגדר הזה ואינן מפי הקב"ה בתורה
@10 **עיניכם הראות** . עתה בא להזהיר בפרטי המצות ויתחיל בעבודת כוכבים שהיא שורש לכולן
@12 וטעם "ראה למדתי אתכם" - ראה שאני מלמד אתכם היום, כמו שאמר (דברים יא יג): "אשר אנכי מצוה אתכם היום", ו(דברים ד ח): "אשר אנכי נותן לפניכם היום".
@12 או יאמר למדתי מפני שהזכיר לעשות כן בקרב הארץ, כלומר, ראה בעת בואך לארץ שלמדתי אתכם חקים ומשפטים כאשר צוני ה' אלהי.
@12 והנה, מתחלה דיבר על הדבר שהיא כלל לכל, עשה ולא תעשה; ועתה יזהיר בחוקים, שהם גזרותיו, ובמשפטים, שהם הדינים, כי אלו הם צריכין חזוק יותר, מפני העלם טעם החוקים, ומפני כי במשפט יעמידו ארץ.
@12 ואמר לעשות כן בקרב הארץ, להזהיר על כולם, כי יש חוקים רבים ומשפטים שאינן נוהגין בחוצה לארץ; או ירמוז שעיקר המצות כולן בארץ, כמו שרמזתי בסוד הארץ (ויקרא יח כה).
@13 ואמר כי בחוקים ובמשפטים תועלות גדולות, שהם תפארת לעושיהם מן האדם, ואפילו שונאיהם ישבחו אותם בהם.
@14 ועוד, שהם תועלת גדולה שאין כמותה, שהשם יהיה קרוב להם בכל קראם אליו, וכן העמים יתבוננו בזה וידעו כי החוקים נעשים בחכמה ובינה לקרבה אל האלהים וייראו מהם, וזהו שאמר כי מי גוי גדול.
@15 ועוד, שהחוקים והמשפטים בעצמם הם צדיקים, ישרים וטובים בישוב העם והמדינות.
@16 **רק השמר לך וגו' פן תשכח את הדברים** .
@16 (קטע:רש"י על דברים ד ט): "אז כשלא תשכחום ותעשום על אמתתם תחשבו חכמים ונבונים ואם תעוותו אותם מתוך שכחה תחשבו שוטים", לשון רש"י.
@16 ואינו נכון כלל, אבל הכתוב הזה לפי דעתי מצות לא תעשה, הזהיר בה מאד, כי כאשר אמר שנזהר בכל המצות ונשמור החוקים והמשפטים לעשותם, חזר ואמר "רק אני מזהירך מאד להשמר ולשמור עצמך מאד מאד לזכור מאין באו אליך המצות, שלא תשכח מעמד הר סיני מכל הדברים אשר ראו עיניך הקולות והלפידים, את כבודו ואת גדלו ודבריו אשר שמעת שם מתוך האש, ותודיע כל הדברים אשר ראו עיניך במעמד הנכבד ההוא לבניך ולבני בניך עד עולם".
@16 ופירש הטעם, כי השם עשה המעמד ההוא כדי שתלמדו ליראה אותו כל הימים ואת בניכם תלמדון לדורות עולם, אם כן עשו אתם ככה ואל תשכחו אותו.
@16 והנה, קודם שיזכיר הדברות שנאמרו שם, הזהיר במצות לא תעשה שלא נשכח דבר מן המעמד ההוא ולא נסירהו מלבנו לעולם, וצוה במצות עשה שנודיע בו לכל זרענו מדור לדור כל מה שהיה שם בראיה ובשמיעה.
@16 והתועלת במצוה הזאת גדולה מאד, שאם היו דברי התורה באים אלינו מפי משה בלבד, אע"פ שנבואתו נתאמתה באותות ובמופתים, אם יקום בקרבנו נביא או חולם חלום ויצונו בהפך מן התורה ונתן אלינו אות או מופת יכנס ספק בלב האנשים; אבל כשתגיע אלינו התורה מפי הגבורה לאזנינו ועינינו הרואות אין שם אמצעי, נכחיש כל חולק וכל מספק, ונשקר אותו, לא יועילהו אות ולא יצילהו מופת מן המיתה בידינו, כי אנחנו היודעים בשקרותו.
@16 זהו שאמר שם (שמות יט ט): "וגם בך יאמינו לעולם", כי כשנעתיק גם כן הדבר לבנינו, ידעו שהיה הדבר אמת בלא ספק כאלו ראוהו כל הדורות, כי לא נעיד שקר לבנינו ולא ננחיל אותם דבר הבל ואין בם מועיל, והם לא יסתפקו כלל בעדותנו שנעיד להם אבל יאמינו בודאי שראינו כולנו בעינינו וכל מה שספרנו להם.
@16 והענין הזה יבוא עוד בפרשת (דברים יג ב): "כי יקום בקרבך נביא או חולם חלום וגו'", וכבר הזכרתיו שם בפרשת "בחדש השלישי" (שמות יט ט).
@19 **וידבר ה' אליכם מתוך האש** . כבר פירשתי הדבר במקומו (שמות יט כ) שהם שמעו דבור השם הגדול יתברך מתוך האש שראו אשו הגדולה והשיגוה והוגד להם בזה בריתו בעשרת הדברים כי בכולן שמעו הקול מתוך האש ושאר המצות צוה אותי בעת ההיא ללמד אתכם כי כבר אני נאמן לנביא לה' במה שראיתם כמו שאמר וגם בך יאמינו לעולם כמו שפירשתי (בפסוק ט)
@22 **ונשמרתם מאד לנפשתיכם** . יזהירם פן יטעו אחר הקול אשר שמעו ויעשו השחתה לקצץ בנטיעות ואמר תחלה תבנית זכר או נקבה באדם שמהם יהיה קול ואחר כן הזכיר כל אשר בארץ בבהמה ובעוף וברמש האדמה ובדגי הים ואחר כן חזר אל צבא השמים
@26 **אשר חלק ה' אלהיך אתם לכל העמים** . כי לכולם כוכב ומזל וגבוהים עליהם מלאכי עליון כגון הנאמר בדניאל שר מלכות פרס ושר מלכות יון ובעבור כן יעשו להם אלהים מהם ויעבדום ואמר ואתכם לקח ה' כי אתם חלק השם לא תקימו עליכם שר או עוזר זולתו כי הוא הוציא אתכם מכור הברזל שהייתם בתוך מצרים בכור אש ועצים והוציא אתכם משם כנגד שריהם שעשה בהם שפטים ולולי שהפילם לא הייתם יוצאים כי היו הם במעלתם שלא תצאו והנה עשה כל זה כדי שתהיו לו נחלה ותהיו לשמו הגדול סגולה מכל העמים
@28 **וטעם וה' התאנף בי על דבריכם** . שהחזיר במקום הזה כלומר אותי צוה ה' בעת ההיא ללמד אתכם המצות לעשותכם אותם בארץ אשר אתם עוברים שמה ועתה קחו מפי תורה כי אנכי מת בארץ הזאת ולא אוכל ללמדם אתכם בארץ ואל תשכחו שם מה שלמדתי אתכם ולא מה שראיתם בסיני ועל דרך האמת יאמר השמרו מאד לנפשותיכם פן תשחיתון כי השם התאנף בי מדאגה מדבר זה פן תשכחו אתם ברית השם אלהיכם באש האוכלת בראש ההר ותעשו תמונת כל וזה טעם אשר צוך ה' אלהיך וכבר נרמז זה בסדר חקת התורה ורש"י כתב אשר צוך ה' אלהיך שלא תעשה והוא פשוטו של מקרא והמשכיל יבין הפסוקים האלה על אמתתם וטעם כי ה' אלהיך אש אכלה הוא כאשר ראיתם בראש ההר והכוונה שהוא מדת הדין המקנא בע"ז ומן הכתוב הזה תבין בכל הנזכר במשנה תורה תמיד "ה' אלהיך"
@32 **כי תוליד בנים ובני בנים ונושנתם** . ענין הכתוב הזה, שיזכיר ויאמר: כי תוליד בנים ובני בנים, ובעבור היותכם ישָנים בארץ ותשבו לבטח, אולי תשכחו את השם; העידותי בכם היום שתאבדו מהר, כי לא יאריך לכם, מאחר שתעבדו עבודה זרה.
@32 והפרשה הזו, אע"פ שהיא אזהרה, לא נאמרה בלשון "אם", והטעם, כי הוא כמתנבא על עניינם, וידבר בלשון ישמש בשני פנים, בלשון אזהרה ובלשון עתיד לבא, יאמר שיעשו ויהיה להם ככה ולא יגזור עליהם. ומפני זה אמרו רבותינו (גיטין פח א) שרמז לגלות בית ראשון במלת "ונושנתם" בגימטריא, והיתה קבלה בידם כי יש בפרשה הזאת רמז לזמן הגלות, וכאשר בא עליהם התבוננו בה בינה.
@32 ואמר "ועשיתם פסל תמונת כל", ולא אמר "ועבדתם אותו" או "והשתחויתם לו" אבל אמר "והשחתם", כי הפסל בכאן תמונת כל, ומפני השחתה יאסור אותו, כאשר פירשתי למעלה.
@34 **ונשארתם מתי מספר בגוים** . יאמר שנשאר מועטים בכל גוי וגוי מכל הגוים אשר ינהג אותנו שם כי בארבע רוחות השמים יפזר אותנו אבל בכללנו רבים אנחנו שבח לאל
@35 **ועבדתם שם אלהים** . משאתם עובדים לעובדיהם אתם עובדים להם לשון רש"י וכבר פירשתי סודו כי היושב בחוצה לארץ כאלו עובד עבודה זרה ומעשה ידי אדם מלמעלה למטה כמו שהזכרתי בסדר אחרי מות (ויקרא יח כה) וטעם ולא יאכלון ולא יריחון לומר שהם אבן דומם כאשר היו מתחילה אין בהם רוח חיים כלל אפילו כחיי האדם כי מתחלה אמר לא יראון ולא ישמעון לומר שאיננו אלוה ולא יראה בעני עובדיו ולא ישמע תפלתם ומצרתם לא יושיעם וחזר ואמר שאפילו חיים גרועים כחיי האדם אין בהם והנה העושה אותם נכבד מהם או יהיה טעם הכתוב כנגד כבוד עליון לומר אשר לא יראו בצרת עובדיהם ולא ישמעון תפלתם ולא יאכלון שלא תצא אש מלפניהם ותאכל את קרבנותם ולא יריחון בריח ניחוחיהם ותפש הכתוב לשון סתם שאין בהם החושים האלו כלל
@37 **ושבת עד ה' אלהיך ושמעת בקלו** . גם זה רמז לגאולת בבל ששבו אל השם והתודו לפניו ושמעו לקול הנביאים אשר הקים להם ולפיכך הבטיחם שלא ישחיתם ולא ישכח ברית אבותם כאשר אמר (ויקרא כו מב) וזכרתי את בריתי יעקוב וגו' ובסוף הספר ירמוז לגאולה העתידה כאשר פירשתי (שם בפסוק טז) ואזכרנו עוד בע"ה (להלן כח מב)
@39 **כי שאל נא לימים ראשונים** . יאמר לא ימחול ולא יאריך השם לכם על ע"ז ועל ההשחתה בפסל וכל תמונה כי עשה עמכם מה שלא עשה כן לכל גוי מעולם שהשמיעך קול אלהים מדבר מתוך האש למען תהיה יראתו על פניכם ותייחדו אותו ולא תשחיתו ולקח אתכם לו גוי מקרב גוי במסות באותות ובמופתים שלא תעבדו לזולתו והנה הראית בעיניך כל זה לדעת כי ה' הוא האלהים הוא אחד ושמו אחד ואין עוד מלבדו כי מן השמים השמיעך את קולו ללמדך בזה מוסר השכל ועל הארץ הראך את אשו הגדולה בוערת עד לב השמים ודבריו כולם שמעת מתוך האש ויוציאך בפניו כמו על פניו (בראשית לב כב) בכחו הגדול אשר בפניו ואחרי שהשם הגדול הוא האלהים בשמים ממעל ועל הארץ מתחת ואין עוד תשמור מצותיו וחקותיו למען ייטב לך בשמים ממעל ולמען תאריך ימים על הארץ מתחת
@48 **אז יבדיל משה שלש ערים** . פירש ר"א ביום שהבדיל משה שלש ערים אז אמר דברי הברית ואינו נכון אבל הוא כפשוטו כי משה אסף כל ישראל לבאר להם התורה ופתח להם בדברי התוכחות וכאשר אמר בפניהם תוכחותיו במה שעשו והאזהרות על ע"ז ועל יחוד השם והשלים להם שישמרו חוקיו ומצותיו למען ייטב להם אז אמר במעמדם לפניהם עתה נקיים המצוה אשר צונו השם ותהיינה בצר במדבר ורמות בגלעד וגולן בבשן ערי מקלט לנוס שמה כל רוצח בשגגה ואע"פ שאינן קולטות עד שיבדלו אותם שבארץ כנען אמר מצוה שבאה לידינו נקיים אותה למען ייטב לנו ואחרי כן קרא בקול גדול אל כל ישראל שהיו שם ואמר אליהם (להלן ה א) שמע ישראל את החקים ואת המשפטים וגו' כי עתה יפתח במצות ובביאור התורה כאשר פירשתי בתחלת סדר אלה הדברים
@54 **ויירשו את ארצו ואת ארץ עוג מלך הבשן מערוער וגו'** . והטעם כי שב להזכיר מה שאמר בתחלת הספר הזה (לעיל א ד) כי ביאור התורה הזה אחרי הכותו את סיחון מלך האמורי אשר יושב בחשבון ואת עוג מלך הבשן אשר יושב בעשתרות באדרעי היה והוסיף בכאן לפרש כי היה הביאור גם אחרי שירשו את כל ארצם כלומר שחלקה להם לשני המטות וחצי המטה
@61 **אנכי עומד בין ה' וביניכם בעת ההוא להגיד לכם את דבר ה'** . כי הוא היה עולה להר ושומע דברי השם ויורד ואומר להם עד שדבר השם עמהם פנים בפנים וזה רמז אל כל מה שנזכר בפרשת בחדש השלישי מתחלת כה תאמר לבית יעקב עד ויאמר אליו ה' לך רד (שמות יט ג-כד) ור"א אמר כי זה אחר מעמד הר סיני והטעם הוא דבר עמכם פנים בפנים ומאותו היום הייתי אני עומד בין השם וביניכם ואינו נכון והנכון בעיני כי ירמוז למה שפירשנו שם (כ ז) כי ישראל לא הבינו מפי הגבורה אלא אנכי ולא יהיה לך ושאר הדברות משה הוא המגיד להם מה שיאמר השם וזהו להגיד לכם את דבר ה' לפרש לכם כל דבור ודבור וטעם בין ה' וביניכם כי בעת הדברות היה הוא קרוב אל מקום השכינה יותר מהם כי הם הרחיקו לעצמם כאשר פירשתי שם (כ טו) וזהו כי יראתם ולא עליתם בהר שלא קרבתם אליו כאשר היה לכם רשות על כן הייתי אני עומד ביניכם ובין מקום הכבוד באמצע כי רחוק היה ביניכם וביניו ומשם הייתי אני מגיד הדברות
@61 "לאמר" - מוסב על דבר ה' עמכם בהר מתוך האש לאמר לשון רש"י ואמר ר"א אל תשית לבך בעבור היות מלת לאמר רחוקה כי כן רבים והמדבר לא הפסיק פסוקים ולא פרשיות ונכון יותר שנדביק להגיד לכם את דבר ה' לאמר כלשון והגדת לבנך ביום ההוא לאמר (שם יג ח) ולדעתי אין צורך כלל אבל טעמו כי יראתם מפני האש ולא עליתם בהר לאמר לא נעלה כי יראנו מפני האש יזכיר כי הם הגידו לו כן בפירוש ולא ממחשבתו יאמר כן
@62 **כאשר צוך ה' אלהיך** . קודם מתן תורה במרה שם שם לו חק ומשפט לשון רש"י ואם כן גם מצות כבוד אב ואם יהיה במרה והרב לא הזכיר שם אלא שבת פרה אדומה ודינין והנראה בעיני על דרך האמת בזה גם בכל משנה תורה כי משה ידבר כמפי הגבורה כמו שאמר (להלן יא יג יד) והיה אם שמוע תשמעו אל מצותי אשר אנכי מצוה אתכם היום לאהבה את ה' אלהיכם ולעבדו בכל לבבכם ובכל נפשכם ונתתי מטר ארצכם בעתו ואין משה הנותן מטר על פני הארץ ולא הנותן עשב בשדה אבל הדבור בתורה בזכור ובמשנה תורה בשמור ולכן יאמר משה בכל מקום במשנה תורה "ה' אלהיך" ובתורה יזכיר שם המיוחד בלבד זולתי בעשרת הדברות כמו שאמר (שמות כ א) וידבר אלהים וגו' והבן זה
@70 **ושורך וחמורך** . לבאר שיאסר גם בעבודת האדמה שהם חיי האדם וכענין שאמר (שם לד כא) בחריש ובקציר תשבות אמר כאן למען ינוח עבדך ואמתך כמוך וזכרת כי עבד היית וגו' לבאר כי בו יצוה במנוחת העבד כמוך בעבור שהיית עבד והניח לך השם וגם אתה תניח לעבדך והנה טעמו כשינוח עבדך ואמתך כמוך תזכור כי עבד היית וגו'
@71 **וטעם על כן צוך לעשות את יום השבת** . צוה שתעשה כן ביום השבת כך פירש ר"א ואינו נכון ואנו אומרים בקדוש היום "כי יום זה תחלה למקראי קדש זכר ליציאת מצרים" כאשר נאמר בו "זכר למעשה בראשית" והרב אמר בספר המורה (ב לא) כי המאמר הראשון הוא כבוד היום והדורו וכאשר אמר (שמות כ יא) על כן ברך ה' את יום השבת ויקדשהו ועל כן הזכיר טעם "כי ששת ימים עשה ה'" אבל בכאן יזהיר אותנו לשמור השבת בעבור היותנו עבדים במצרים עובדים כל היום על כרחנו ולא היתה לנו מנוחה והוא יצונו עתה לשבות ולנוח כדי שנזכיר חסדי השם עלינו בהוציאו אותנו מעבדות למנוחה והנה בשבת בכללה שני טעמים להאמין בחידוש העולם כי יש אלוה בורא ולזכור עוד החסד הגדול שעשה עמנו שאנחנו עבדיו אשר קנה אותנו לו לעבדים גם זה אינו מחוור אצלי כי בהיותנו שובתים ולא נעשה מלאכה ביום השביעי אין לנו בזה זכרון ליציאת מצרים ואין לרואה אותנו בטלים ממלאכה ידיעה בזה רק היא כשאר כל המצות אבל יהיה בו זכר למעשה בראשית שנשבות ביום ששבת השם וינפש והראוי יותר לומר כי בעבור היות יציאת מצרים מורה על אלוה קדמון מחדש חפץ ויכול כאשר פירשתי בדבור הראשון (שם שם ב) על כן אמר בכאן אם יעלה בלבך ספק על השבת המורה על החדוש והחפץ והיכולת תזכור מה שראו עיניך ביציאת מצרים שהיא לך לראיה ולזכר הנה השבת זכר ליציאת מצרים ויציאת מצרים זכר לשבת כי יזכרו בו ויאמרו השם הוא מחדש בכל אותות ומופתים ועושה בכל כרצונו כי הוא אשר ברא הכל במעשה בראשית וזה טעם על כן צוך ה' אלהיך לעשות את יום השבת והנה לא פירש כאן טעם השביתה כי ששת ימים עשה ה' וגו' שכבר הוזכר זה פעמים רבות בתורה אבל אמר בקצרה "ויום השביעי שבת לה' אלהיך" שהוא יתברך שבת בו וינפש ובאר להם כי מיציאת מצרים ידעו שהוא אמר והיה העולם ושבת ממנו ועל דרך האמת נוכל עוד להוסיף בזה כי הדבור הזה בשמור ליראה את השם הנכבד והנורא ועל כן יצונו שנזכור את היד החזקה והזרוע הנטויה שראינו ביציאת מצרים וממנו לנו היראה כמו שאמר (שם יד לא) וירא ישראל את היד הגדולה אשר עשה ה' במצרים וייראו העם את ה' ועל כן צוך ה' אלהיך לעשות את יום השבת שתהא כנסת ישראל בת זוגו לשבת כנרמז בדברי רבותינו (ב"ר יא ט) והמשכיל יבין
@73 **ולא תענה ברעך עד שוא** . לאסור להעיד על חברו אפילו דבר שאינו כלום ולא יתחייב בו כלום בבית דין כגון שיעיד אמר פלוני ליתן לזה מנה ולא קנה מידו כי "שוא" דבר בטל
@75 **מתוך האש הענן והערפל** . ביאור ל"מתוך האש" כי ענן וערפל סביביו קול גדול ולא יסף מתרגמינן ולא פסק לפי שמדת בשר ודם אינן יכולין לדבר דבריהם בנשימה אחת ומדת הקב"ה אינו כן לא היה פוסק ומשלא היה פוסק לא היה מוסיף לפי שקולו חזק וקיים לעולם ד"א לא יסף לא הוסיף להראות באותו פומבי לשון רש"י והכתוב אמר (שמות יט יט) ויהי קול השופר הולך וחזק מאד ואמרו (מכילתא יתרו ד) למה רך בתחלה לשכך את האוזן במה שיכולה לשמוע ואולי בקול השופר היה כן אבל קול השם בעשרת הדברות היה שוה והנכון כי האומר לא פסק עשה יסף מן ונאספה שמחה וגיל (ירמיהו מח לג) תוסף רוחם יגועון (תהלים קד כט) שענינם לדעתו המנע הדבר יאמר כי לא נמנע גדלו ותקפו עד שהשלים כל הדברות וכן אמר ויתנבאו ולא יספו (במדבר יא כה) ועל דרך הפשט ולא יסף שלא יסף להיות עוד גדול כמוהו ועל דרך האמת יאמר כי כל הדברים האלה שמעו קול גדול ולא יסף להשמיע אל כל קהלכם אלא קול אחד כי אותו קול בלבד השיגו הם וכבר פירשתי ענין זה שם (שמות יט כ) וכל הפרשה
@79 **אשר שמע קול אלהים חיים מדבר מתוך האש** . אמר ר"א כי טעם "חיים" להבדיל בין אלהים ובין הצבא כי לא יתנועע הוא מעצמו ויתכן לפרש שהזכיר כן לומר שהשומע קול אלהים שעמו מקור החיים תדבק נפשו ביסודה ולא תחיה עוד חיי בשרים ויהושע אמר (יהושע ג י יא) בזאת תדעון כי אל חי בקרבכם הנה ארון הברית אדון כל הארץ אם כן וישבע בחי העולם (דניאל יב ז) שבועה בשמו הגדול
@80 **ואת תדבר אלינו** . התשתם כחי כנקבה שנצטערתי עליכם ורפיתם את ידי כאשר ראיתי שאינכם חרדים להתקרב אליו מאהבה וכי לא היה יפה ללמוד מפי הגבורה ולא ממני לשון רש"י מדברי אגדה ואם כן יאמר שדאג להם אבל השם הודיעו כי מיראתו עשו וטוב להם והענין כאשר פירשתי שם (שמות כ טו) כי היו חושבים שירצה להשמיעם כל התורה והרצון היה לפניו להשמיעם עשרת הדברות בלבד כאשר בקשו ודע כי עתה בקשו ממשה שלא ישמעו קול השם הנכבד לא ביום הזה ולא בדור מן הדורות לעולם דלאו כל שעתא ושעתא מתרחיש ניסא ואינם חפצים במעמד כזה אבל יאמינו בנביאים ויעשו כל רצון השם על פיהם וכן יאמר להם משה (להלן יח טו טז) נביא מקרבך מאחיך כמוני יקים לך ה' אלהיך אליו תשמעון ככל אשר שאלת מעם ה' אלהיך בחורב וגו' וכל הפרשה ההיא אם כן השאלה הזאת לדורות היתה
@82 **מי יתן והיה לבבם זה להם ליראה אותי** . בעבור היות רשות האדם בידו להצדיק ולהרשיע והכל בידי שמים חוץ מיראת שמים יאמר הכתוב כן והוא כלשון בני אדם ועל דרך האמת הוא כמו ויאמר לאדם הן יראת אדני היא חכמה וסור מרע בינה (איוב כח כח) וכך אמרו בשכרן של מצות (מנחות כט) ראה שחותכין בשרו של ר' עקיבא במקולין אמר לו רבונו של עולם זו תורה וזה שכרה השיב לו הקב"ה שתוק כך עלה במחשבה לפני ותבין זה ממה שאמר (פסוק כח) ואתה פה עמוד עמדי
@84 **ועשו בארץ** . פרשתיו (ויקרא יח כה)
@85 **ושמרתם לעשות כאשר צוה ה' אלהיכם אתכם** . זו אזהרה על עשרת הדברות שצוה אותם השם מפיו ואחרי כן יזהיר בשאר המצות שאמרו הם לשמוע ממשה ולעשות ולכך אמר (להלן ו א) וזאת המצוה החקים והמשפטים אשר צוה ה' אלהיכם ללמד אתכם כי השם הודה לדבריכם וצוה אותי ללמד אתכם שאר כל התורה למען תחיון שימלא מספר ימיכם וטוב לכם בכל הטובה אשר יעד לכם בפרשת אם בחקותי וזולתה והארכתם ימים בארץ שתנחילו אותה לזרעכם לעולם
@88 **למען תירא את ה' אלהיך** . יאמר שצוה השם ללמד אתכם התורה והמצוה והחקים והמשפטים לעשותם בארץ בעבור שתירא את ה' אלהיך כי עיקר כל המצוה יראת ה' זה דעת ר"א ואיננו נכון בעיני שיהיה "למען תירא" ו"למען יאריכון ימיך" האחד טעם המצות בעבור שתירא והשני שנזכר בהם למען שיאריכון ימיך אבל יאמר שצוה השם אותי שתלמדו המצות ותעשו אותם למען שתזכה ותירא את ה' אלהיך לשמור מצותיו אתה ובנך ובן בנך כל ימי היות האדם על פני האדמה לעולם כי בעבור עשות המצות תזכה שיהיו לך בנים יראי השם ויעמדו על פני האדמה לעולם ויעמוד זרעכם ושמכם לפניו כל הימים ולמען יאריכון ימיך בארץ שהיא נחלת ה' והנה הכל לטובתך כי חפץ ה' להצדיקך ולזכות אותך
@89 **ושמרת לעשות אשר ייטב** . הנה מצוך שתשמור לעשות אשר ייטב לך ארץ זבת חלב ודבש דבק עם "לרשתה" (בפסוק א) ואם הוא רחוק או יהיה חסר בי"ת כמו הנמצא בית ה' (מלכים ב יב יא) לשון ר"א ואם כן יחסר עוד מ"אשר תרבון מאד" "בו" או "בעבורו" ואין צורך כי "למען יאריכון ימיך" נמשך לכאן וטעמו "למען אשר ייטב לך" או מלת "אשר" בעצמה תשמש כן כמו ויסירה מגבירה אשר עשתה מפלצת (מלכים א טו יג) בעבור שעשתה וכן באשר את אשתו (בראשית לט ט) בעבור שאת אשתו וכן הכתוב אשר אנכי מצוך היום אשר ייטב לך וגו' ולמען תאריך ימים על האדמה (לעיל ד מ) ושיעור הכתוב ושמעת ישראל ושמרת לעשות למען אשר ייטב לך ואשר תרבון מאד כאשר דבר ה' אלהי אבותיך לתת לך ארץ זבת חלב ודבש וגו' כלומר למען שייטב לך בתתו לך ארץ טובה ורחבה כמו שאמר למטה (פסוק יח) למען אשר ייטב לך ובאת וירשת את הארץ וכמוהו ויתן לו בית ולחם אמר לו (מלכים א יא יח)
@90 **שמע ישראל ה' אלהינו** . גם בזה מצוה שיבאר כי בדבור אנכי ה' אלהיך יהיה היחוד וכמו שאמרו (מכילתא בחדש ה) רבי נתן אומר מכאן תשובה למינים שהם אומרים שתי רשויות הן שכשעמד הקב"ה על הר סיני ואמר אנכי ה' אלהיך מי מיחה כנגדו אבל בא לבאר המצוה הזו והזכיר אותה אחר עשרת הדברות לפי שהוא שרש באמונה וכל מי שאינו מודה בה כופר בעיקר כעובד ע"ז ה' אלהינו ה' אחד ה' שהוא אלהינו ולא אלהי האומות עתיד להיות ה' אחד כמו שנאמר (זכריה יד ט) ביום ההוא יהיה ה' אחד ושמו אחד לשון רש"י ואתה צריך להתבונן בזה כי שנה הכתוב כאן לומר "ה' אלהינו" ולא אמר "אלהיך" כמו שאומר בכל מקום שמע ישראל אתה עובר היום וגו' כי ה' אלהיך (להלן ט א ג) שמע ישראל אתם קרבים היום וגו' כי ה' אלהיכם (להלן כ ג ד) וכן בכל הפרשיות שידבר עם ישראל יזכיר ה' אלהיכם או ה' אלהיך וגם בכאן אמר ואהבת את ה' אלהיך אבל הזכיר ביחוד "ה' אלהינו" כי עשה עם משה את הגדולות ואת הנוראות לעשות לו שם תפארת והנה דל"ת אחד גדולה לרמוז על מה שכתוב (ישעיהו סג יב) בוקע מים מפניהם לעשות לו שם עולם ולכך תקנו בקריאת שמע ברוך שם כבוד מלכותו לעולם ועד ואמרו משל לבת מלך שהריחה ציקי קדרה וכו' (פסחים נו) כי משה אמר בתורה ברמז וחזר ואמר ואהבת את ה' אלהיך כלשון הפרשיות במשנה תורה
@91 **בכל לבבך** . על דעת המדרש (ספרי ואתחנן ו) הלב הנזכר כאן הוא הכח המתאוה כענין תאות לבו נתת לו (תהלים כא ג) אל תחמוד יפיה בלבבך (משלי ו' כה) אם כן בכל נפשך הנפש המשכלת וכן והיתה נפש אדוני צרורה בצרור החיים (שמואל א כה כט) וכדברי רבותינו שדורשין בגמרא (ברכות נד) מכאן יהרג ואל יעבור יהיה "בכל נפשך" תוספת מפני שאמר בכל לבבך ובכל מאדך אמר גם כן בכל נפשך וטעם שתאהבנו כנפשך שתתן אותה באהבה או שנקראו היסורין או האברים חצי הנפש ובהריגה יאמר בכל נפשך ור"א אמר כי "נפשך" המתאוה כמו כנפשך שבעך (להלן כג כה) נפש שבעה תבוס נופת (משלי כז ז) אל תתנני בנפש צרי (תהלים כז יב) "ובכל לבבך" הוא הדעת והוא כנוי לרוח המשכלת כי היא המרכבה הראשונה לו וכמוהו חכם לב יקח מצות (משלי י ח) ודברו קרוב בפירוש "בכל לבבך" ממה שאמר והיו הדברים האלה וגו' על לבבך וטעם ובכל מאדך כלומר מאד מאד והטעם רב רב אהוב אותו ועל דעת רבותינו (ברכות נד) בכל ממונך ויקרא הממון "מאד" כי יכנה אותו ברבוי כמו שקורא לו "המון" טוב מעט לצדיק מהמון רשעים רבים (תהלים לז טז) והנם ככל המון ישראל (מלכים ב ז יג) ויקרא "חיל" ישאו על כתף עירים חיליהם (ישעיהו ל ו) חילך כל אוצרותיך (ירמיהו יז ג) את החיל הזה (להלן ח יז) יאמר בכל רבוי ממונך וכמוהו אשר שב אל ה' בכל לבבו ובכל נפשו ובכל מאדו (מלכים ב כג כה) מפני התנדבו בענין ביעור ע"ז ועשיית הפסח וענין האהבה בארו אותו רבותינו והמפורש שבדבריהם מה שאמרו בספרי (עקב) שמא תאמר הריני לומד תורה בשביל שאקרא חכם בשביל שאשב בישיבה בשביל שאאריך ימים בשביל שאזכה לעולם הבא ת"ל לאהבה וגו' ואשר אמר להם משה תמיד למען ייטב לך ולמען תאריך ימים (לעיל ד מ) ולמען תחיו ובאתם וירשתם את הארץ (לעיל ד א) יזהירם ביראה על דרך התוכחות לומר שאם יחטאו לא יירשו את הארץ או לא יאריכו ימים עליה או שהחסיד צריך להיות אוהב וירא כמו שאמרו (ירושלמי ברכות פ"ט ה"ה) עשה מאהבה ועשה מיראה עשה מאהבה שאין אוהב שונא ועשה מיראה שאם באת לבעוט אל תבעוט וכבר נתבאר זה בדברי החכמים
@93 **ושננתם לבניך** . גם אלה מצות מבוארות נרמזו כבר כי מאחר שצוה במצות חקת עולם לדורותיכם ביני ובין בני ישראל אות היא לעולם (שמות לא יז) זאת בריתי אשר תשמרו ביני וביניכם ובין זרעך אחריך (בראשית יז י) הנה אנחנו מצווים שידעו בנינו המצות ואיך ידעו אותם אם לא נלמדם וכן וקשרתם לאות על ידך והיו לטטפת בין עיניך כבר נאמר (שמות יג ט) ובאר בכאן "וקשרתם" שיהיו מונחים בקשירה וירמוז גם כן לקשר של תפילין שקבלו רבותינו הלכה למשה מסיני (מנחות לה) והוסיף בכאן מצות המזוזה וכתבתם על מזזות ביתך ובשעריך שלא נזכרה ואולי גם זו מבוארת נרמזה שם במצות ולזכרון בין עיניך למען תהיה תורת ה' בפיך וטעם "ובשעריך" ובמזוזות שאר שעריך כגון שערי הערים והמדינות כמו באחד שעריך (להלן טו ז)
@96 **והיה כי יביאך ה' אלהיך וגו'** . יזכיר בכאן כי ברבות הטובה יזכור ימי עניו ומרודו שהיה עבד במצרים ולא ישכח את השם שהוציאו מן העבדות ההוא לטובה הזאת אבל יזכור חסדיו תמיד ויירא אותו ויעבוד לפניו כעבד לאדוניו ועל דעת רבותינו (חולין יז) ירמוז עוד כי הטוב ההוא אשר ימצא בבתים המלאים מותר אפילו היו שם דברים הנאסרים בתורה כגון קדלי דחזירי או כרמים נטועים כלאים או ערלה ואפילו בבורות יתכן שהיה בחציבתן דבר אסור בטיח אשר בהן או הזכיר הבורות דרך מליצה להזכיר רבוי הטובה והשליט אותם בכל הנמצא בארץ במותר ובאסור והנה הותרו להן כל האיסורין זולתי אסור ע"ז כמו שיבאר עוד (להלן ז כה) לא תחמוד כסף וזהב עליהם ולקחת לך וגו' ולכך יזכיר כאן בפרשה שאחרי כן (להלן ז ה) מזבחותיהם תתצו וגו' לאבד ע"ז ומשמשיה ושאר כל הנמצא בארץ מותר והיה ההיתר הזה עד שאכלו שלל אויביהם ויש אומרים בשבע שכבשו וכן נראה בגמרא בפרק ראשון ממסכת חולין (שם) והרב כתב בהלכות מלכים ומלחמותיהם (רמב"ם פ"ח ה"א) חלוצי צבא משיכנסו בגבול הגוים וישבו מהם מותר להם לאכול נבלות וטרפות ובשר חזיר וכיוצא בו אם רעב ולא מצא מה יאכל אלא מאכלים אלו האסורים וכן שותה יין נסך ומפי השמועה למדו ובתים מלאים כל טוב ערפי חזירים וכיוצא בהן ואין זה נכון שלא בשביל פקוח נפש או רעבון בלבד הותר בשעת מלחמה אלא לאחר שכבשו הערים הגדולות והטובות וישבו בהן התיר להם שלל אויביהם ולא בכל חלוצי צבא אלא בארץ אשר נשבע לאבותינו לתת לנו כמו שמפורש בענין וכן יין נסך שהזכיר אינו אמת שבכל איסורי ע"ז היא עצמה ומשמשיה ותקרובת שלה הכל אסור שנאמר (להלן ז כו) שקץ תשקצנו ותעב תתעבנו כי חרם הוא ואם לא נתכוון הרב אלא להתיר סתם יינן במלחמה וכי למה הוצרכנו לדבר זה איסורי תורה הותרו גזרות של דבריהם יהיו אסורות
@99 **וטעם את ה' אלהיך תירא** . כי אחר שצוה באהבה יזכיר ליראה אותו שלא יחטא ויענש ואתו תעבד לעשות כל אשר צוך כעבד שומר מצות אדוניו ויתכן שיהיה זה רמז לעבודת הקרבנות לשמו וכך אמרו בספרי (ראה ס) בפסוק אחרי ה' אלהיכם תלכו ואותו תיראו ואת מצותיו תשמרו ובקולו תשמעו ואותו תעבודו (להלן יג ה) עבודו בתורתו עבודו במקדשו ירצה לפרש כי אחרי שהזהיר בשמירת כל המצות כלן ולשמוע בקולו יהיה "ואותו תעבודו" לעבדו במקדש בקרבנות ובשיר ובהשתחואות שם כי זה יקרא עבודה כמו שאמר (במדבר יח ז) עבודת מתנה אתן את כהונתכם ואמר (שם פסוק כג) ועבד הלוי ודרשו עוד "עבודו בתורתו" ללמוד התורה ולהגות בה וגם היא עבודה לפניו ולפי זה "ואותו תעבוד" ג"כ בקרבנות ור"א אמר את ה' אלהיך תירא שלא תעבור על מצות לא תעשה ואותו תעבוד במצות עשה ואיננו נכון מפני שאמר בכתוב האחר ואותו תיראו ואת מצותיו תשמורו ואותו תעבודו
@99 "ובשמו תשבע" - אינו מצוה שישבע אבל הוא אזהרה כי בשמו בלבד תשבע לא בשם אל אחר על כן כתוב אחריו לא תלכון אחרי אלהים אחרים שלא תלכו אחריהם בדבר מכל אלו שלא תיראו מהם ולא תעבדו אותם ולא תשבעו בשמם אבל בגמרא של מסכת תמורה דרשו אותו בשבועת אמת דשריא אמרו בשמו תשבע דאמר רחמנא למה לי אם אינו ענין לשבועת הדיינין דנפקא ליה משבועת ה' תהיה בין שניהם תנהו ענין לשבועות דעלמא דשריין ואם אינו ענין לשבועה דמצוה דנפקא ליה מן ובו תדבקון (להלן יג ה) תנהו ענין לשבועה דחול וראיתי עוד בתנחומא אמר להן הקב"ה לישראל לא תהיו סבורין שהותר לכם להשבע בשמי אפילו באמת אין אתם רשאין להשבע בשמי אלא אם יהיו בך כל המדות הללו את ה' אלהיך תירא שתהיה כאותן שנקראו יראי אלהים אברהם יוסף איוב ואותו תעבוד שתהא מפנה עצמך לתורה ולמצות ולא יהיה לך עבודה אחרת לכך נאמר ואותו תעבוד ובו תדבק וכי אפשר לו לאדם להדבק בשכינה והלא כבר נאמר (לעיל ד כד) כי ה' אלהיך אש אוכלה הוא אלא לומר לך כל המשיא בתו לתלמיד שקורא ושונה והעושה לו פרקמטיא והמהנהו מנכסיו זהו שאמר ובו תדבק אם יש לך כל מדות אלו אתה רשאי להשבע ואם לאו אי אתה רשאי להשבע עד כאן לשון אגדה זו והנה פירוש הכתוב לדעתם "ובשמו תשבע" רשות שיתיר לנו להשבע בשמו על דרך הכבוד כאלו אמר את ה' אלהיך תירא אבל בשמו תשבע ולא תירא מזה ומפני ששם ההיתר הזה אחר היראה והעבודה דרשו שאין היתר לשבועה אלא לאחר כל המדות הללו או יאמר את ה' אלהיך תירא ותהיה יראתו גדולה על פניך עד שתהיה שמו לך לשבועה כי גם ברצותך לקיים כל דבר תשבע בשמו להרע ולא תמיר ויהיה פירוש "ואותו תעבוד" לדעתם שתהיה לו בכל עת כעבד הקנוי המשרת לפני אדוניו תמיד שעושה מלאכת רבו עיקר וצרכי עצמו עראי עד שיבא מזה מה שאמרו (אבות ב יב) וכל מעשיך יהיו לשם שמים שאפילו צרכי גופו לשם עבודת האל יהיו יאכל ויישן ויעשה צרכיו כדי קיום הגוף לעבוד ה' כענין שאמרו (בראשית רבה ט ו) והנה טוב מאד זו שינה וכי שינה טובה היא מתוך שהוא ישן קמעא הוא עומד ועוסק בתורה ויתכוין בכל צרכי הגוף למקרא שכתוב (תהלים קמו ב) אהללה ה' בחיי אזמרה לאלהי וגו' וזה פירוש נכון
@102 **לא תנסו את ה' אלהיכם** . פירוש כאשר נסיתם במסה שלא תאמר אם יש ה' בקרבנו לעשות לנו נסים או שנצליח בהיותנו עובדים לפניו ונשבע לחם ונהיה טובים נשמור תורתו כי הכוונה שם כך היתה שאם יראו שהשם יתן להם מים בנס מאתו ילכו אחריו במדבר ואם לא יעזבוהו ונחשב להם לעון גדול כי אחרי שנתאמת אצלם באותות ובמופתים כי משה נביא השם ודבר ה' בפיהו אמת אין ראוי לעשות עוד שום דבר לנסיון והעושה כן איננו מנסה הנביא רק השם יתברך הוא מנסה לדעת היד ה' תקצר ולכך אסר לדורות לנסות התורה או הנביאים כי אין ראוי לעבוד השם על דרך הסתפק או שאלת מופת ונסיון כי אין רצון השם לעשות נסים לכל אדם ובכל עת ואין ראוי לעבדו על מנת לקבל פרס אלא אולי ימצא בעבודתו ולכתו בדרכי התורה צער ואסון וראוי שיקבל הכל במשפט צדק ולא כאשר אמרו אוילי עמנו (מלאכי ג יד) וכי הלכנו קדורנית מפני ה' ולכך אמר הכתוב בכאן שמור תשמרו מצותיו ועדותיו שהם הנסים שעשה לכם מכבר להיות לכם לעדות כגון הפסח והמצה והסוכה ותשמרו חקיו אע"פ שלא תדעו טעמם כי באמת ייטב לכם בסוף אין צורך לנסיון בתורה ובמצות אחרי שכבר נתאמת אצלכם שהוא מאתו יתברך וכן בכל דבר נביא המנוסה והמוחזק בנביא אמת באותות ובמופתים כדין התורה לא תנסו את דבריו בכל גמול ובכל עונש שיאמר לכם ולא תסתפקו ביכלתו יתעלה אבל האמינו בתורתו ותאמינו בנביאיו והצליחו והנה הבטיח כי סוף הכבוד לבוא בירושת הארץ ונצוח האויבים כי היא הטובה הגדולה והצריכה לאותו הדור ואחרי כן אמר כי גם לדורות הבאים אין צורך לנסיון בעשיית המצות אלא שישאלו מאבותיהם וזקניהם ויגידו להם אמתת התורה והמצות כאשר יפרש (פסוק כ) כי ישאלך בנך וגמר הפרשה
@104 **ועשית הישר והטוב בעיני ה'** . על דרך הפשט יאמר תשמרו מצות השם ועדותיו וחקותיו ותכוין בעשייתן לעשות הטוב והישר בעיניו בלבד ו למען ייטב לך הבטחה יאמר כי בעשותך הטוב בעיניו ייטב לך כי השם מטיב לטובים ולישרים בלבותם ולרבותינו בזה מדרש יפה אמרו זו פשרה ולפנים משורת הדין והכוונה בזה כי מתחלה אמר שתשמור חקותיו ועדותיו אשר צוך ועתה יאמר גם באשר לא צוך תן דעתך לעשות הטוב והישר בעיניו כי הוא אוהב הטוב והישר וזה ענין גדול לפי שאי אפשר להזכיר בתורה כל הנהגות האדם עם שכניו ורעיו וכל משאו ומתנו ותקוני הישוב והמדינות כלם אבל אחרי שהזכיר מהם הרבה כגון לא תלך רכיל (ויקרא יט טז) לא תקום ולא תטור (שם פסוק יח) ולא תעמוד על דם רעך (שם פסוק טז) לא תקלל חרש (שם פסוק יד) מפני שיבה תקום (שם פסוק לב) וכיוצא בהן חזר לומר בדרך כלל שיעשה הטוב והישר בכל דבר עד שיכנס בזה הפשרה ולפנים משורת הדין וכגון מה שהזכירו בדינא דבר מצרא (ב"מ קח) ואפילו מה שאמרו (יומא פו) פרקו נאה ודבורו בנחת עם הבריות עד שיקרא בכל ענין תם וישר
@106 **וטעם כי ישאלך בנך מחר לאמר מה העדות** . שישאל תחלה על מה יעידו אלה המצות הנקראים "עדות" בעבור שהם זכר לנפלאותיו ועדות בהם כגון המצה והסוכה והפסח והשבת והתפילין והמזוזה ומה החקים כי נעלם טעמם בתורה והמשפטים ישאל מה המשפטים שנעשה במצות האלה שנסקול העושה מלאכה בשבת ונשרוף הבא על אשה ואמה ונכה את הארבעים לזורע כלאים כי משפטי ישוב המדינות בדיני השור והבור והשומרים ושאר הדינין שבתורה צדיקים וטובים הן כל רואיהם יכירון וצוה בתשובת השאלה הזאת שנגיד לשואל כל ענין יציאת מצרים והכוונה בזה הוא הטעם במה שאמר בעשרת הדברות (לעיל ה ו) אשר הוצאתיך מארץ מצרים כי יתכוון שנודיע לבן השואל כי ה' הוא הבורא והחפץ והיכול כאשר נתבאר לנו ביציאת מצרים וזה טעם "לעינינו" כי אנחנו היודעים ועדים מן האותות והמופתים שראינו שם כי השם אלהינו הוא האלהים בשמים ובארץ ואין עוד מלבדו כי כל זה יודע ביציאת מצרים כאשר פירשתי בדבור הראשון (שמות כ ב) והנה ראוי לנו לתת כבוד לשמו כי הוא בוראנו ואשר הגדיל חסדו עמנו ויצונו לעשות את החקים האלה הנזכרים בעדות חקים ומשפטים ליראה אותו בעשותנו העדות זכר לנפלאותיו לטוב לנו בעשיית החקים כי טובים הם אין בהם חק שתהיה בו רעה כלל אע"פ שלא נתברר טעמם לכל
@117 **בך בחר ה' אלהיך להיות לו לעם סגלה** . שאין לך קצין שוטר ומושל בכל מלאכי מעלה אבל אתה סגולת ה' תחת ידו ולכך לא תטעה לעבוד ע"ז מאלהי העמים וכבר הזכרתי זה פעמים רבות וזה טעם לא מרבבם מכל העמים כי היה ראוי שיהיו הרבים למלך כענין שכתוב (משלי יד כח) ברב עם הדרת מלך ויפקיד שרי צבאות בראש הנשארים ואתם המעט ואע"פ כן חשק בכם ויבחר בכם וטעם חשק שנקשר עמכם בקשר אמיץ שלא יפרד מכם לעולם מלשון וחשוקיהם כסף (שמות כז י) ויבחר בכם מכל העמים שתהיו אתם סגולה ונחלה לו כי הבחירה בכל מקום ברירה מן האחרים ואמר הטעם כי מאהבת ה' אתכם בחר בכם שראה אתכם ראויים להתאהב לפניו ונבחרים לאהבה יותר מכל העמים ולא הזכיר בזה טעם מן הבחירה כי הנבחר לאוהב היודע לסבול את אוהבו בכל הבא עליו ממנו וישראל ראויים לכך מכל עם כמו שאמרו (ביצה כה) שלשה עזים הם ישראל באומות כי יעמדו לו בנסיונות או יהודאי או צלוב (שמו"ר מב ט) וטעם בכם בעבור אבותיכם שהגיע ענינם עד שנשבע להם כדי שלא יגרום החטא ותבטל הבטחתם ועל כן הוציא אתכם מארץ מצרים ביד חזקה ויפדך רמז שהכה אותם תחתיך כענין שנאמר (ישעיהו מג ג) נתתי כפרך מצרים כוש וסבא תחתיך
@120 **וידעת** . מיציאת מצרים כי ה' אלהיך הוא האלהים שברא שמים וארץ כאשר פירשתי (לעיל ו כ) ועוד תדע מזה שהוא האל הנאמן שלא ישוב דברו ריקם והוא שומר הברית והחסד לאוהביו ולשומרי מצותיו יראי שמו לאלף דור בזרעם כאשר שמר לך ברית אבותיך ותדע כי הוא משלם לשונאיו רשעם אל פני כל אחד מהם להאבידו כאשר האביד את המצרים ולא אחר להם והמדה הזאת אשר הזכיר אמת לעולם אע"פ שיש רשע מאריך ברעתו לא יהיה לו כן רק מפני המדה הזאת הנזכרת שהוא שומר החסד והנה עשה שום טובה שצריך לשלם לו אם כן אין במדותיו של הקב"ה אלא שתי מדות הללו משלם טובה תחת טובה ומשלם רעה תחת רעה ויתכן כי שונאיו המוחלטים מכחישים באלהותו (ו) אין להם זכות כלל וכמו שאמרו (קהלת רבה ז לב) אמר רבי יאשיה מפני שלשה דברים הקב"ה מאריך אפים לרשעים בעולם הזה שמא יעשו תשובה או עשו מצות שהקב"ה ישלם שכרן בעולם הזה או שמא יצאו מהן צדיקים שכך מצינו שהאריך אפים לאחז ויצא ממנו חזקיהו וגם לאמון ויצא ממנו יאשיהו וגם לשמעי ויצא ממנו מרדכי וכל אלו אינם בכלל שונאיוויש במלת "אל פניו" סוד ברשע וטוב לו והחזיר ושמרת את המצוה וגו' לומר לכן תשמור את המצוה ואת החקים ואת המשפטים שלא תהיה משונאיו האובדים אבל תהיה מאוהביו ושומרי מצותיו הנזכרים לטובה ולחיים
